insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('da000000-0000-0000-0000-000000000001', 'mrcp2', '86e464f3-d548-4c83-9f1d-7c8e126e789b',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('da000000-0000-0000-0000-000000000001', 'A', 'Continue trastuzumab at the same dose and monitor LVEF again in 3 months', false, 'Ruled out because continuing trastuzumab through a significant asymptomatic LVEF decline risks progression to symptomatic heart failure; guidelines mandate withholding therapy at this threshold.', 1),
('da000000-0000-0000-0000-000000000001', 'B', 'Permanently discontinue trastuzumab and switch to an alternative HER2-targeted agent with no cardiotoxicity monitoring required', false, 'Ruled out because trastuzumab cardiotoxicity is usually reversible, so permanent discontinuation is premature; also, other HER2-targeted agents (e.g. pertuzumab, T-DM1) carry their own cardiotoxicity risk and still require monitoring.', 2),
('da000000-0000-0000-0000-000000000001', 'C', 'Reduce the trastuzumab dose by 50% and continue treatment', false, 'Ruled out because trastuzumab dosing is not adjusted for cardiotoxicity in the way chemotherapy doses are for other toxicities; the correct action is temporary cessation, not dose reduction.', 3),
('da000000-0000-0000-0000-000000000001', 'D', 'Withhold trastuzumab, start guideline-directed heart failure therapy, and repeat echocardiography in 3-4 weeks before deciding on rechallenge', true, 'Correct. Trastuzumab-induced cardiotoxicity is typically reversible and mediated by disruption of HER2-dependent cardiomyocyte repair rather than direct myocyte destruction (unlike anthracyclines). An asymptomatic LVEF fall of this magnitude (>10 points from baseline to below 50%) warrants withholding trastuzumab, initiating ACE inhibitor/beta-blocker therapy, and reassessing LVEF after a short interval; treatment can often be resumed once LVEF recovers.', 4),
('da000000-0000-0000-0000-000000000001', 'E', 'Proceed directly to endomyocardial biopsy to confirm trastuzumab-induced myocardial injury before any treatment change', false, 'Ruled out because biopsy is not required to diagnose trastuzumab cardiotoxicity, which is a clinical/echocardiographic diagnosis; it would delay appropriate management unnecessarily.', 5),
('da000000-0000-0000-0000-000000000002', 'A', 'Await blood culture results before starting antibiotics, as the patient is clinically well', false, 'Ruled out because delaying antibiotics in febrile neutropenia pending cultures significantly increases mortality risk; empirical treatment must start immediately.', 1),
('da000000-0000-0000-0000-000000000002', 'B', 'Admit and start empirical broad-spectrum intravenous antibiotics (e.g. piperacillin-tazobactam) immediately after blood cultures, without waiting for culture results', true, 'Correct. Febrile neutropenia (fever ≥38°C with neutrophils <0.5 x10^9/L) is a medical emergency regardless of how well the patient appears, because occult Gram-negative sepsis can progress to septic shock within hours. Blood cultures (peripheral and, if present, from any central line) should be taken but must not delay empirical broad-spectrum antibiotics, which should be given within one hour of presentation.', 2),
('da000000-0000-0000-0000-000000000002', 'C', $x$Start oral co-amoxiclav and manage as an outpatient given the patient's clinical stability$x$, false, 'Ruled out because although low-risk febrile neutropenia pathways exist using validated risk scores (e.g. MASCC), the default and safest approach for a neutrophil count this low is admission and IV antibiotics; oral outpatient management requires formal risk stratification and specific low-risk criteria being met, not offered here.', 3),
('da000000-0000-0000-0000-000000000002', 'D', 'Give granulocyte colony-stimulating factor (G-CSF) alone without antibiotics, since neutrophil recovery is the priority', false, 'Ruled out because G-CSF does not treat established infection or sepsis risk; antibiotics are the immediate priority, with G-CSF considered as an adjunct in selected high-risk cases, not a substitute.', 4),
('da000000-0000-0000-0000-000000000002', 'E', 'Perform CT chest/abdomen/pelvis to identify a septic focus before starting treatment', false, 'Ruled out because imaging should not delay empirical antibiotic therapy in febrile neutropenia; source identification proceeds in parallel with, not before, treatment.', 5),
('da000000-0000-0000-0000-000000000003', 'A', 'Oxaliplatin; advise the patient to avoid cold exposure and continue treatment, as this acute cold-induced neuropathy is usually transient and reversible between cycles', true, 'Correct. Oxaliplatin causes a characteristic acute, cold-triggered peripheral and pharyngolaryngeal dysaesthesia that occurs within hours of infusion and resolves within days, distinct from the cumulative chronic sensory neuropathy that develops with repeated dosing. Acute symptoms are managed with cold avoidance (including avoiding cold drinks/air) and do not usually require dose modification, though cumulative chronic neuropathy would prompt dose reduction or discontinuation.', 1),
('da000000-0000-0000-0000-000000000003', 'B', '5-fluorouracil; discontinue treatment immediately due to risk of cardiac ischaemia', false, 'Ruled out because the described symptoms (cold-triggered dysaesthesia, pharyngolaryngeal tightness) are the classic acute neurotoxicity of oxaliplatin, not 5-FU; 5-FU toxicity of concern is coronary vasospasm presenting as chest pain, not this neuropathy pattern.', 2),
('da000000-0000-0000-0000-000000000003', 'C', 'Folinic acid; no action is required as this drug has no associated neurotoxicity and the symptoms are unrelated', false, 'Ruled out because folinic acid (leucovorin) is not neurotoxic; attributing the symptoms to it and dismissing them would miss the recognised oxaliplatin toxicity requiring counselling.', 3),
('da000000-0000-0000-0000-000000000003', 'D', 'Oxaliplatin; discontinue treatment immediately as this indicates irreversible grade 4 neuropathy', false, 'Ruled out because this presentation describes the acute, reversible cold-dysaesthesia syndrome, not irreversible cumulative sensory neuropathy; immediate discontinuation is not warranted at this stage.', 4),
('da000000-0000-0000-0000-000000000003', 'E', '5-fluorouracil; switch to capecitabine to avoid further neurotoxicity', false, 'Ruled out because 5-FU is not the causative agent here, and capecitabine (an oral prodrug of 5-FU) would not address oxaliplatin-related neurotoxicity, which is the actual issue.', 5),
('da000000-0000-0000-0000-000000000004', 'A', 'Continue bleomycin at full dose since the patient is asymptomatic with normal oxygen saturations', false, 'Ruled out because waiting for symptoms or hypoxia risks progression to established, irreversible pulmonary fibrosis; DLCO decline is used precisely because it identifies toxicity before clinical deterioration.', 1),
('da000000-0000-0000-0000-000000000004', 'B', 'Reduce the bleomycin dose by 50% and continue monitoring DLCO monthly', false, 'Ruled out because there is no validated dose-reduction strategy for bleomycin pulmonary toxicity that reliably prevents progression; the standard approach is discontinuation once significant DLCO decline is detected.', 2),
('da000000-0000-0000-0000-000000000004', 'C', 'Discontinue bleomycin and continue the remaining cycles with etoposide and cisplatin alone', true, 'Correct. Bleomycin causes dose-dependent pulmonary toxicity (pneumonitis progressing to fibrosis) that can be fatal, and a significant decline in DLCO is an early, sensitive marker preceding clinical or radiographic changes. Current practice is to stop bleomycin when DLCO falls significantly (typically >10-15%) even in asymptomatic patients, continuing the remainder of the regimen without it, as EP alone remains effective and avoids progression to irreversible fibrosis.', 3),
('da000000-0000-0000-0000-000000000004', 'D', 'Start high-dose corticosteroids and continue bleomycin unchanged', false, 'Ruled out because steroids are used to treat established bleomycin pneumonitis, not as a strategy to permit continued bleomycin dosing in the face of declining DLCO; the priority is stopping the causative drug.', 4),
('da000000-0000-0000-0000-000000000004', 'E', 'Switch to high-flow supplemental oxygen therapy and continue bleomycin, since hyperoxia is not a concern in this context', false, 'Ruled out because supplemental oxygen is actually a specific risk factor that can precipitate or worsen bleomycin lung injury (including perioperatively), and continuing bleomycin regardless is inappropriate; oxygen should in fact be used cautiously in patients who have received bleomycin.', 5),
('da000000-0000-0000-0000-000000000005', 'A', 'Remove the cannula immediately, apply a warm compress, and elevate the limb without further specific treatment', false, 'Ruled out because warm compresses are used for certain vesicants (e.g. vinca alkaloids) but are contraindicated for anthracycline extravasation, where cooling (not warming) is used alongside dexrazoxane; also, drug should be aspirated before removing the cannula.', 1),
('da000000-0000-0000-0000-000000000005', 'B', 'Continue the infusion at a slower rate while monitoring the site closely, as extravasation cannot be confirmed without blood return testing', false, 'Ruled out because clinical signs (pain, erythema, swelling, blistering) are sufficient to diagnose extravasation and mandate immediate cessation; continuing a vesicant infusion into extravasated tissue causes worsening necrosis.', 2),
('da000000-0000-0000-0000-000000000005', 'C', 'Inject hyaluronidase locally into the extravasation site as the specific antidote for anthracycline extravasation', false, 'Ruled out because hyaluronidase is the specific antidote for vinca alkaloid and taxane extravasation, not anthracyclines; using it here would not address doxorubicin-induced tissue injury.', 3),
('da000000-0000-0000-0000-000000000005', 'D', 'Apply topical DMSO (dimethyl sulfoxide) alone and continue chemotherapy through the same cannula once symptoms settle', false, 'Ruled out because although topical DMSO has been used adjunctively in some anthracycline extravasation protocols, the priority intervention is IV dexrazoxane, and the cannula/limb should not be reused for further chemotherapy after extravasation.', 4),
('da000000-0000-0000-0000-000000000005', 'E', 'Stop the infusion immediately, aspirate residual drug from the cannula, leave the cannula in situ initially, and arrange urgent administration of intravenous dexrazoxane', true, 'Correct. Doxorubicin is a potent vesicant, and extravasation can cause severe, progressive tissue necrosis. The immediate steps are to stop the infusion, aspirate as much drug as possible through the existing cannula before removing it, and give the specific antidote dexrazoxane intravenously (into a different limb) within 6 hours, which significantly reduces the risk of ulceration and need for surgical debridement.', 5),
('da000000-0000-0000-0000-000000000006', 'A', 'Direct capecitabine-induced cardiotoxicity from coronary vasospasm; the patient should be switched to intravenous 5-fluorouracil, which does not carry this risk', false, 'Ruled out because the described syndrome (mucositis, diarrhoea, hand-foot syndrome, myelosuppression) is not cardiotoxicity, and 5-FU carries the same DPD-dependent toxicity risk as capecitabine since it is metabolised by the same pathway.', 1),
('da000000-0000-0000-0000-000000000006', 'B', 'UGT1A1 polymorphism causing reduced glucuronidation; the patient should be switched to irinotecan-based therapy instead', false, 'Ruled out because UGT1A1 polymorphisms predispose to irinotecan toxicity, not fluoropyrimidine toxicity; switching to irinotecan in a patient with unknown UGT1A1 status and no evidence of this mechanism would not address the actual problem and could introduce new risk.', 2),
('da000000-0000-0000-0000-000000000006', 'C', 'Simple dose-dependent mucosal toxicity unrelated to any pharmacogenomic factor; the same regimen can be continued at a reduced dose after recovery', false, 'Ruled out because the recurrent, disproportionately severe toxicity pattern across two separate fluoropyrimidine exposures strongly suggests an underlying metabolic (DPD) abnormality rather than simple dose-related toxicity, and rechallenge at reduced dose risks further severe or fatal toxicity without addressing the mechanism.', 3),
('da000000-0000-0000-0000-000000000006', 'D', 'Thiopurine methyltransferase (TPMT) deficiency; azathioprine co-administration should be reviewed as the likely cause', false, 'Ruled out because the patient is not described as taking azathioprine, and TPMT deficiency is relevant to thiopurine toxicity, not fluoropyrimidine toxicity; this is a distractor pairing an unrelated pharmacogenomic pathway with this clinical picture.', 4),
('da000000-0000-0000-0000-000000000006', 'E', 'Dihydropyrimidine dehydrogenase (DPD) deficiency, causing impaired fluoropyrimidine catabolism and drug accumulation; capecitabine should be permanently discontinued and DPD genotyping/phenotyping considered for the patient', true, 'Correct. DPD is the rate-limiting enzyme in fluoropyrimidine catabolism; partial or complete DPD deficiency leads to markedly elevated and prolonged drug exposure, producing severe, often life-threatening toxicity (mucositis, diarrhoea, myelosuppression, hand-foot syndrome) even at standard doses. This presentation with recurrent severe toxicity on fluoropyrimidines should prompt permanent discontinuation and consideration of DPD testing, which is now recommended prior to fluoropyrimidine initiation where available.', 5),
('da000000-0000-0000-0000-000000000007', 'A', 'Increase the dose and frequency of folinic acid rescue, ensure aggressive intravenous hydration with urinary alkalinisation, and consider glucarpidase if the level remains critically elevated or renal function continues to worsen', true, 'Correct. Delayed methotrexate clearance with rising creatinine indicates methotrexate-induced nephrotoxicity, which risks a vicious cycle of reduced clearance and prolonged toxic exposure (mucositis, myelosuppression, further renal injury). Management escalates folinic acid dosing based on the measured level, ensures hydration and urinary alkalinisation (methotrexate is more soluble at alkaline pH), and reserves glucarpidase (which rapidly cleaves methotrexate to an inactive metabolite) for cases of significantly elevated levels with renal impairment where clearance is severely compromised.', 1),
('da000000-0000-0000-0000-000000000007', 'B', 'Stop folinic acid rescue, as it is only indicated when methotrexate levels are normal', false, 'Ruled out because folinic acid rescue is precisely intended to counteract toxic methotrexate exposure and must be increased, not stopped, when clearance is delayed and levels remain high.', 2),
('da000000-0000-0000-0000-000000000007', 'C', 'Administer high-dose corticosteroids as first-line treatment for methotrexate-induced nephrotoxicity', false, 'Ruled out because corticosteroids have no established role in reversing methotrexate nephrotoxicity or accelerating its clearance; the priority is escalated folinic acid, hydration/alkalinisation and consideration of glucarpidase.', 3),
('da000000-0000-0000-0000-000000000007', 'D', 'Proceed to urgent haemodialysis as the first-line intervention to remove methotrexate', false, 'Ruled out because standard haemodialysis removes methotrexate poorly and is not first-line; glucarpidase is the preferred intervention for severe toxic accumulation, with dialysis reserved for specific refractory situations under specialist guidance.', 4),
('da000000-0000-0000-0000-000000000007', 'E', 'Reassure the patient that levels above nomogram thresholds at 24 hours are expected and require no change in management', false, 'Ruled out because a level exceeding the nomogram threshold with rising creatinine indicates a high risk of severe toxicity and requires active escalation of rescue therapy, not reassurance.', 5),
('da000000-0000-0000-0000-000000000008', 'A', 'Continue immunotherapy unchanged and manage symptomatically with loperamide alone, as infective causes have been excluded', false, 'Ruled out because immune-related colitis of this severity requires withholding immunotherapy and starting corticosteroids; loperamide alone risks progression to severe colitis and masks response to appropriate treatment.', 1),
('da000000-0000-0000-0000-000000000008', 'B', 'Start empirical broad-spectrum antibiotics for presumed neutropenic enterocolitis', false, 'Ruled out because there is no neutropenia or evidence of infection described, and antibiotics do not address immune-mediated colitis, which is the most likely diagnosis given the checkpoint inhibitor exposure and negative infective workup.', 2),
('da000000-0000-0000-0000-000000000008', 'C', 'Start oral corticosteroids (e.g. prednisolone 1 mg/kg) and temporarily withhold immunotherapy pending clinical response', true, 'Correct. This represents grade 2 immune-related colitis (diarrhoea 4-6 stools/day above baseline, or here escalating toward grade 3 territory but still without severe features) following combination checkpoint inhibitor therapy, after infective causes have been excluded. Standard management is to withhold the checkpoint inhibitors and start corticosteroids, with endoscopic assessment considered if symptoms fail to improve, since immune-related colitis can progress to severe, life-threatening colitis or perforation if undertreated.', 3),
('da000000-0000-0000-0000-000000000008', 'D', 'Permanently discontinue all immunotherapy and do not consider future rechallenge under any circumstances', false, 'Ruled out because grade 2 immune-related colitis that responds to corticosteroids typically allows for cautious rechallenge (often with the anti-PD-1 agent alone) once symptoms resolve and steroids are weaned, so permanent discontinuation is not an absolute at this severity grade.', 4),
('da000000-0000-0000-0000-000000000008', 'E', 'Arrange urgent surgical review for likely bowel perforation based on the stool frequency alone', false, 'Ruled out because there are no peritonitic signs, haemodynamic compromise, or other features suggesting perforation; this presentation is consistent with grade 2 colitis manageable medically, not an acute surgical abdomen.', 5),
('da000000-0000-0000-0000-000000000009', 'A', 'Empirically reduce the chemotherapy dose by 25% in all future cycles without G-CSF support', false, 'Ruled out because dose reduction is not the preferred first strategy after a single febrile neutropenia episode when G-CSF prophylaxis can maintain dose intensity; unnecessary dose reduction can compromise oncological outcomes.', 1),
('da000000-0000-0000-0000-000000000009', 'B', 'Switch to a completely different chemotherapy regimen, as gemcitabine-cisplatin is contraindicated after any episode of febrile neutropenia', false, 'Ruled out because a single febrile neutropenia episode does not mandate regimen change; supportive strategies (G-CSF, dose modification if needed) are tried first.', 2),
('da000000-0000-0000-0000-000000000009', 'C', 'Continue the same regimen and dose without any additional measures, as the neutropenic sepsis has now resolved', false, 'Ruled out because doing nothing accepts a high recurrence risk of febrile neutropenia; secondary prophylaxis with G-CSF (or dose modification if G-CSF is inappropriate) should be instituted.', 3),
('da000000-0000-0000-0000-000000000009', 'D', 'Add prophylactic granulocyte colony-stimulating factor (G-CSF) support starting 24-72 hours after chemotherapy in subsequent cycles, without reducing the chemotherapy dose', true, 'Correct. Following a first episode of febrile neutropenia, especially in a regimen not previously classified as high-risk, primary or secondary G-CSF prophylaxis is added in subsequent cycles to reduce neutropenia duration and severity, allowing chemotherapy to continue at full, effective dose rather than being empirically reduced, which could compromise treatment efficacy in a potentially curable or disease-controlling context.', 4),
('da000000-0000-0000-0000-000000000009', 'E', 'Start prophylactic oral antibiotics (e.g. ciprofloxacin) for the duration of chemotherapy instead of G-CSF', false, 'Ruled out because while antibacterial prophylaxis has a role in specific very high-risk settings (e.g. prolonged severe neutropenia in haematological malignancy induction), G-CSF is the standard secondary prophylaxis strategy after febrile neutropenia in solid tumour chemotherapy to reduce neutropenia duration, not long-term antibiotic prophylaxis.', 5),
('da000000-0000-0000-0000-000000000010', 'A', 'Reassure the patient that this hearing loss is temporary and will fully resolve once chemotherapy is completed', false, 'Ruled out because cisplatin ototoxicity is typically permanent, not temporary; false reassurance would be clinically inaccurate and could lead to inadequate monitoring.', 1),
('da000000-0000-0000-0000-000000000010', 'B', 'Arrange baseline and serial audiometric monitoring before subsequent cycles, and discuss with the oncology team whether dose modification or a switch to carboplatin is appropriate given the emerging ototoxicity', true, 'Correct. Cisplatin causes cumulative, dose-dependent, largely irreversible sensorineural hearing loss beginning at high frequencies, through damage to cochlear outer hair cells. Once ototoxicity is identified, ongoing audiometric monitoring guides decisions about continuing full-dose cisplatin, dose modification, or (where oncologically appropriate, e.g. in some germ cell tumour contexts efficacy trade-offs must be carefully weighed) considering carboplatin substitution, since further cisplatin exposure risks progression to hearing loss affecting speech frequencies.', 2),
('da000000-0000-0000-0000-000000000010', 'C', 'Increase the cisplatin dose to complete treatment more quickly and avoid prolonged ototoxic exposure', false, 'Ruled out because increasing the dose would worsen cumulative ototoxicity, which is dose-dependent; this is the opposite of appropriate management.', 3),
('da000000-0000-0000-0000-000000000010', 'D', 'Start oral corticosteroids as first-line treatment to reverse the hearing loss', false, 'Ruled out because there is no established role for corticosteroids in reversing established cisplatin-induced sensorineural hearing loss; some otoprotective strategies (e.g. sodium thiosulfate in specific paediatric contexts) exist but are not standard corticosteroid therapy.', 4),
('da000000-0000-0000-0000-000000000010', 'E', 'Refer for cochlear implantation immediately, as this is the only management option available at this stage', false, 'Ruled out because cochlear implantation is a consideration for severe, established, disabling hearing loss unresponsive to hearing aids, not the immediate next step in a patient still undergoing active treatment with only high-frequency loss so far; the priority now is monitoring and treatment modification discussion.', 5),
('da000000-0000-0000-0000-000000000011', 'A', 'Clostridioides difficile colitis; start oral vancomycin and await stool toxin results before further action', false, 'Ruled out because although C. difficile should be excluded, the clinical picture (right-sided/caecal predominance, profound neutropenia, this specific CT pattern) is classic for neutropenic enterocolitis rather than typical C. difficile colitis, which usually shows more diffuse colonic changes.', 1),
('da000000-0000-0000-0000-000000000011', 'B', 'Acute appendicitis; arrange emergency laparoscopic appendicectomy', false, 'Ruled out because in a profoundly neutropenic patient with this CT pattern (caecal/ascending colon wall thickening rather than isolated appendiceal changes), neutropenic enterocolitis is far more likely than appendicitis, and emergency surgery in this setting carries very high morbidity/mortality; it is reserved for specific complications.', 2),
('da000000-0000-0000-0000-000000000011', 'C', 'Neutropenic enterocolitis (typhlitis); manage conservatively with bowel rest, broad-spectrum antibiotics covering Gram-negative and anaerobic organisms, and close surgical review, reserving surgery for complications such as perforation or uncontrolled sepsis', true, 'Correct. Neutropenic enterocolitis (typhlitis) is a life-threatening complication of profound neutropenia, classically following cytotoxic chemotherapy for haematological malignancy, presenting with right-sided abdominal pain, fever and characteristic caecal/ascending colon wall thickening on CT. First-line management is conservative — bowel rest, IV fluids, broad-spectrum antibiotics (covering Gram-negatives and anaerobes, e.g. piperacillin-tazobactam) and correction of coagulopathy/neutropenia support — with surgery reserved for perforation, uncontrolled haemorrhage, or clinical deterioration despite medical therapy, as mortality with surgery in profoundly neutropenic/thrombocytopenic patients is high.', 3),
('da000000-0000-0000-0000-000000000011', 'D', 'Chemotherapy-induced mucositis affecting the colon; manage with oral analgesia and reassurance, no antibiotics required', false, 'Ruled out because this presentation with fever, neutropenia, localised bowel wall thickening and bloody diarrhoea represents a life-threatening bowel infection/inflammation requiring broad-spectrum antibiotics, not simple mucositis management.', 4),
('da000000-0000-0000-0000-000000000011', 'E', 'Ischaemic colitis secondary to chemotherapy-induced vasculitis; start therapeutic anticoagulation', false, 'Ruled out because there is no evidence supporting a vasculitic/ischaemic process here, and anticoagulation would be inappropriate and potentially dangerous in a patient at risk of bowel wall haemorrhage or perforation.', 5),
('da000000-0000-0000-0000-000000000012', 'A', 'Doxorubicin; stop the drug immediately due to risk of irreversible cardiomyopathy', false, 'Ruled out because the described toxicity is neurological, not cardiac, and doxorubicin is not classically associated with peripheral neuropathy; this distractor pairs the wrong toxicity with the wrong drug.', 1),
('da000000-0000-0000-0000-000000000012', 'B', 'Vinblastine; reduce or hold the dose given evidence of significant peripheral and autonomic neurotoxicity, as this is the dose-limiting toxicity for vinca alkaloids', true, 'Correct. Vinca alkaloids (vinblastine here, and more classically vincristine) cause a dose-dependent peripheral sensorimotor and autonomic neuropathy through microtubule disruption in axonal transport, presenting with constipation/ileus (autonomic), jaw pain, and areflexia progressing to motor weakness/foot drop if unaddressed. Once motor involvement (foot drop) develops, this represents significant neurotoxicity requiring dose reduction or omission to prevent further, potentially irreversible, deficit.', 2),
('da000000-0000-0000-0000-000000000012', 'C', 'Bleomycin; arrange urgent pulmonary function tests as the priority investigation', false, $x$Ruled out because bleomycin's dose-limiting toxicity is pulmonary fibrosis, not peripheral/autonomic neuropathy; the clinical picture described does not fit bleomycin toxicity.$x$, 3),
('da000000-0000-0000-0000-000000000012', 'D', 'Dacarbazine; this is an expected, self-limiting effect requiring no change in treatment', false, $x$Ruled out because dacarbazine's typical toxicities are nausea/vomiting and myelosuppression, not this pattern of peripheral/autonomic neuropathy, and foot drop is not benign or self-limiting — it requires action.$x$, 4),
('da000000-0000-0000-0000-000000000012', 'E', 'Vinblastine; continue at full dose since neuropathy from vinca alkaloids always resolves spontaneously without intervention', false, 'Ruled out because while some vinca alkaloid neuropathy can improve after dose reduction/cessation, it is not reliably self-limiting with continued full-dose treatment, and established motor deficits (foot drop) can become permanent if the causative drug is continued unchanged.', 5),
('da000000-0000-0000-0000-000000000013', 'A', 'Slow the infusion rate and continue, since premedication was already given and reactions rarely recur once initial symptoms are managed', false, 'Ruled out because continuing a taxane infusion during an ongoing severe hypersensitivity reaction with hypotension and bronchospasm risks life-threatening deterioration; the infusion must be stopped and anaphylaxis treated first.', 1),
('da000000-0000-0000-0000-000000000013', 'B', 'Administer additional oral antihistamines only and observe, without stopping the infusion', false, 'Ruled out because oral antihistamines are inadequate for a reaction with haemodynamic compromise and bronchospasm; this requires immediate cessation of the infusion and parenteral anaphylaxis treatment including adrenaline.', 2),
('da000000-0000-0000-0000-000000000013', 'C', 'Diagnose primary cardiac event and activate the cardiac catheterisation pathway before considering the infusion as a cause', false, 'Ruled out because the temporal relationship (within minutes of taxane infusion) with flushing, wheeze and hypotension is classic for an infusion-related hypersensitivity reaction, which should be treated as the primary diagnosis and managed accordingly, though cardiac causes are considered if the picture is atypical or unresponsive to treatment.', 3),
('da000000-0000-0000-0000-000000000013', 'D', 'Permanently discontinue all taxane chemotherapy for this patient with no possibility of future taxane use', false, 'Ruled out because although severe reactions require great caution, carefully planned rechallenge with enhanced premedication or formal desensitisation protocols can allow selected patients to safely continue taxane therapy under specialist supervision, so blanket permanent avoidance is not automatically correct.', 4),
('da000000-0000-0000-0000-000000000013', 'E', 'Stop the infusion immediately, manage as anaphylaxis with intramuscular adrenaline, oxygen, IV fluids and antihistamines/further steroids, and once stable discuss a slower rechallenge protocol or desensitisation for future cycles under specialist supervision', true, 'Correct. This presentation (rapid onset, hypotension, bronchospasm, occurring within minutes despite premedication) represents a severe hypersensitivity/anaphylactoid reaction to docetaxel, a recognised taxane toxicity related to the drug vehicle (historically Cremophor-type solvents, though docetaxel uses polysorbate 80) and/or direct complement activation. Immediate management follows standard anaphylaxis protocols: stop the infusion, give IM adrenaline, oxygen, fluids and antihistamines/steroids. Future dosing requires specialist discussion regarding slower infusion, enhanced premedication, or formal desensitisation protocols.', 5),
('da000000-0000-0000-0000-000000000014', 'A', 'Give high-dose dexamethasone immediately and urgently refer for same-day discussion with the clinical oncology/spinal surgery team regarding decompressive surgery versus radiotherapy', true, 'Correct. Malignant spinal cord compression is an oncological emergency where speed of treatment directly determines neurological outcome; high-dose corticosteroids (typically dexamethasone 16 mg/day in divided or loading doses per local protocol) should be given as soon as the diagnosis is suspected/confirmed to reduce cord oedema, without waiting for specialist review. Definitive treatment (surgical decompression, particularly for a single-level compression with preserved but declining function, versus radiotherapy) needs urgent same-day multidisciplinary discussion, as delay beyond 24-48 hours of losing motor function substantially reduces the chance of regaining ambulation.', 1),
('da000000-0000-0000-0000-000000000014', 'B', 'Arrange radiotherapy planning for the next available routine slot within the week, without starting corticosteroids first', false, 'Ruled out because corticosteroids must be started immediately once cord compression is suspected/confirmed, not deferred until radiotherapy planning, and radiotherapy for cord compression should be arranged urgently (same or next day), not as a routine weekly slot.', 2),
('da000000-0000-0000-0000-000000000014', 'C', 'Withhold corticosteroids due to his prostate cancer diagnosis, as steroids may interfere with hormonal therapy response', false, 'Ruled out because there is no such contraindication; corticosteroids are a standard, urgent component of cord compression management regardless of primary tumour type, and delaying them risks further neurological deterioration.', 3),
('da000000-0000-0000-0000-000000000014', 'D', 'Proceed directly to emergency decompressive laminectomy without imaging confirmation of the compression level', false, 'Ruled out because surgical planning requires prior MRI localisation (already obtained here) to guide the approach; the appropriate next step is steroids plus urgent MDT discussion of surgery versus radiotherapy, not proceeding to theatre without a defined plan/MDT input.', 4),
('da000000-0000-0000-0000-000000000014', 'E', 'Manage conservatively with analgesia and physiotherapy alone, as bisphosphonate therapy within the last month suggests bone disease is already being adequately treated', false, 'Ruled out because bisphosphonates treat bone metastases generally but do not address acute cord compression from an epidural mass; this requires emergency steroid therapy and urgent definitive treatment, not conservative management alone.', 5),
('da000000-0000-0000-0000-000000000015', 'A', 'Start emergency radiotherapy alone without tissue diagnosis, as this is the fastest way to relieve the obstruction', false, 'Ruled out because radiotherapy without a tissue diagnosis is generally avoided when the patient is not in extremis, since it can compromise the ability to obtain diagnostic tissue afterward and SCLC (highly likely histology suggested by chemosensitivity considerations) responds very well to chemotherapy — stenting offers faster relief without this trade-off, allowing biopsy first.', 1),
('da000000-0000-0000-0000-000000000015', 'B', 'Give high-dose corticosteroids as the sole definitive treatment and avoid endovascular intervention due to bleeding risk from the tumour', false, 'Ruled out because corticosteroids may have some benefit particularly if there is a lymphoma component or significant peritumoural oedema, but are not definitive treatment for mechanical SVC obstruction with thrombus; endovascular stenting is appropriate and standard, not something to be avoided by default.', 2),
('da000000-0000-0000-0000-000000000015', 'C', 'Manage conservatively with diuretics to reduce venous congestion and reassess in one week', false, 'Ruled out because diuretics do not address the mechanical/thrombotic obstruction and may cause harmful haemoconcentration; this delays effective intervention in a patient with significant, progressive symptoms.', 3),
('da000000-0000-0000-0000-000000000015', 'D', 'Elevate the head of the bed, give supplemental oxygen if hypoxic, arrange urgent endovascular stenting for rapid symptom relief, and start anticoagulation if thrombus is confirmed alongside definitive oncological treatment planning', true, 'Correct. Superior vena cava obstruction (SVCO) from malignancy with significant symptoms (breathlessness, facial/laryngeal swelling) is managed with simple supportive measures (head elevation, oxygen if hypoxic) plus, in this case with mechanical compression and thrombus, endovascular stenting as it provides rapid (within 24-72 hours) symptomatic relief compared with the slower onset of chemotherapy/radiotherapy; anticoagulation is indicated when thrombus is present (once bleeding risk assessed), and histological diagnosis/tumour-specific treatment (SCLC is very chemosensitive) should be arranged in parallel.', 4),
('da000000-0000-0000-0000-000000000015', 'E', 'Perform emergency surgical bypass of the superior vena cava as first-line treatment', false, 'Ruled out because surgical bypass is a high-risk, invasive option reserved for select cases where endovascular stenting is not feasible or has failed; percutaneous stenting is the preferred first-line intervention for rapid relief in malignant SVCO.', 5),
('da000000-0000-0000-0000-000000000016', 'A', 'Immediate intravenous zoledronic acid before any fluid resuscitation, as bisphosphonates work faster than rehydration', false, 'Ruled out because bisphosphonates should be given after (or alongside, but not instead of) adequate rehydration; giving them to a dehydrated patient with renal impairment (creatinine already rising) increases the risk of nephrotoxicity, and rehydration itself has a rapid effect on lowering calcium.', 1),
('da000000-0000-0000-0000-000000000016', 'B', 'Loop diuretics (e.g. furosemide) as first-line therapy to promote calciuresis, without prioritising fluid rehydration first', false, 'Ruled out because loop diuretics are no longer recommended as routine first-line therapy for hypercalcaemia of malignancy; they can worsen dehydration if given before adequate rehydration and are now reserved for specific fluid-overload situations under careful monitoring.', 2),
('da000000-0000-0000-0000-000000000016', 'C', 'Subcutaneous calcitonin as monotherapy without bisphosphonate therapy, given its rapid onset of action', false, 'Ruled out because calcitonin has a rapid but short-lived and often modest effect with tachyphylaxis after 48 hours; it may be used as a bridge in severe/symptomatic cases alongside fluids while awaiting bisphosphonate effect, but is not appropriate as monotherapy replacing bisphosphonate therapy.', 3),
('da000000-0000-0000-0000-000000000016', 'D', 'Aggressive intravenous 0.9% saline rehydration followed by intravenous zoledronic acid once adequately rehydrated', true, 'Correct. Malignancy-associated hypercalcaemia (here likely PTHrP-mediated humoral hypercalcaemia of malignancy from squamous cell carcinoma) causing symptomatic severe hypercalcaemia (>3.5 mmol/L, confusion, AKI) requires initial aggressive IV rehydration with 0.9% saline to correct dehydration and improve renal calcium clearance, followed by an IV bisphosphonate (e.g. zoledronic acid) once rehydrated, which takes effect over 2-4 days and provides more durable calcium lowering than fluids alone.', 4),
('da000000-0000-0000-0000-000000000016', 'E', 'Oral bisphosphonate therapy alone, as intravenous administration is unnecessary in this context', false, 'Ruled out because oral bisphosphonates have poor bioavailability and are not used for acute severe symptomatic hypercalcaemia; IV bisphosphonate therapy is standard in this setting.', 5),
('da000000-0000-0000-0000-000000000017', 'A', 'Diagnose neutropenic sepsis and start broad-spectrum antibiotics as the sole management, without corticosteroids', false, 'Ruled out because although infection should remain on the differential and be appropriately covered, this constellation with rapidly rising white cell count and pulmonary infiltrates temporally linked to ATRA strongly suggests differentiation syndrome, which requires prompt corticosteroids as the specific treatment — omitting steroids risks rapid deterioration.', 1),
('da000000-0000-0000-0000-000000000017', 'B', 'Immediately and permanently discontinue ATRA in all cases of suspected differentiation syndrome', false, 'Ruled out because ATRA is usually continued (with corticosteroids added) in mild-to-moderate differentiation syndrome, since it remains critical to APL treatment; only severe/life-threatening cases warrant temporary discontinuation, and permanent discontinuation is not the default approach.', 2),
('da000000-0000-0000-0000-000000000017', 'C', 'Give aggressive diuresis with high-dose furosemide as the primary intervention, without starting corticosteroids', false, 'Ruled out because while careful fluid management is part of supportive care, the specific and most important intervention is corticosteroid therapy to dampen the underlying inflammatory/cytokine process; diuretics alone do not address the pathophysiology.', 3),
('da000000-0000-0000-0000-000000000017', 'D', 'Perform emergency leukapheresis to rapidly reduce the white cell count as first-line management', false, 'Ruled out because leukapheresis is not standard management for differentiation syndrome (unlike hyperleukocytosis with leukostasis in other leukaemias); the specific treatment is corticosteroids, with ATRA continued or paused depending on severity.', 4),
('da000000-0000-0000-0000-000000000017', 'E', 'Start high-dose intravenous dexamethasone promptly and continue ATRA unless the syndrome is severe or life-threatening, in which case temporarily withhold it', true, 'Correct. This presentation (fever, dyspnoea, hypoxia, pulmonary infiltrates, weight gain/oedema, rapidly rising white cell count) shortly after starting ATRA is classic for differentiation syndrome (formerly retinoic acid syndrome), caused by cytokine release and capillary leak from differentiating leukaemic promyelocytes. First-line treatment is prompt high-dose corticosteroids (dexamethasone), which are highly effective; ATRA is usually continued in mild-to-moderate cases because it is also the definitive treatment driving differentiation, but is temporarily withheld in severe/life-threatening cases (e.g. requiring ICU-level respiratory or haemodynamic support) until stabilisation.', 5),
('da000000-0000-0000-0000-000000000018', 'A', 'Transfuse packed red blood cells to correct anaemia as the immediate priority before other interventions', false, 'Ruled out because red cell transfusion increases whole blood viscosity and can precipitate or worsen leukostasis in the context of hyperleukocytosis; it should be avoided or given very cautiously until the white cell count is being actively reduced.', 1),
('da000000-0000-0000-0000-000000000018', 'B', 'Manage expectantly with observation alone, as the platelet count of 28 x10^9/L is the more urgent abnormality requiring prophylactic platelet transfusion first', false, 'Ruled out because symptomatic leukostasis with neurological/visual involvement is immediately life- and organ-threatening and requires urgent cytoreduction; while thrombocytopenia needs monitoring/management, it does not take priority over treating leukostasis, and observation alone is inappropriate.', 2),
('da000000-0000-0000-0000-000000000018', 'C', 'Start emergency cytoreductive therapy (e.g. induction chemotherapy, with leukapheresis considered as an adjunct) alongside hydration and prompt tumour lysis syndrome prophylaxis, avoiding red cell transfusion until the white cell count is controlled', true, 'Correct. Symptomatic hyperleukocytosis with neurological and visual symptoms and retinal haemorrhages indicates leukostasis, a medical emergency from hyperviscosity and vascular occlusion by leukaemic blasts, most classically in AML. Management is emergency cytoreduction (induction chemotherapy started urgently; leukapheresis can be used as an adjunct particularly if chemotherapy must be delayed or in specific high-risk situations) combined with hydration and tumour lysis prophylaxis (given the very high proliferative/lysis burden); red cell transfusion is avoided or given cautiously before white count reduction, as it can further increase blood viscosity and worsen leukostasis.', 3),
('da000000-0000-0000-0000-000000000018', 'D', 'Start therapeutic anticoagulation with low molecular weight heparin, as the retinal haemorrhages suggest a thrombotic process requiring anticoagulation', false, 'Ruled out because leukostasis is caused by leukaemic cell aggregation and vascular occlusion, not a coagulopathic/thrombotic process requiring anticoagulation, and anticoagulation would be dangerous given the co-existing thrombocytopenia and retinal haemorrhages (bleeding risk).', 4),
('da000000-0000-0000-0000-000000000018', 'E', 'Delay treatment until a definitive cytogenetic and molecular diagnosis is confirmed, to tailor cytoreductive therapy precisely', false, 'Ruled out because symptomatic leukostasis is a medical emergency requiring immediate cytoreduction; treatment should not be delayed for complete molecular characterisation, which can continue to inform later therapy.', 5),
('da000000-0000-0000-0000-000000000019', 'A', 'Treat as febrile neutropenia based on the documented history of fever and rigors with a recent neutrophil count in the neutropenic range, starting empirical IV antibiotics promptly after cultures, even though she is currently afebrile in the department', true, 'Correct. A history of a documented fever (≥38°C) at home with rigors, in a patient known to be neutropenic (or at high risk of neutropenia post-chemotherapy) should be treated as febrile neutropenia even if the patient has since become afebrile, since neutropenic sepsis can be rapidly progressive and intermittent fever does not exclude ongoing serious infection; delaying treatment based on a single normal temperature reading in the department is unsafe.', 1),
('da000000-0000-0000-0000-000000000019', 'B', 'Discharge home with safety-netting advice, as she is currently afebrile and looks well', false, 'Ruled out because a documented history of fever with rigors in a neutropenic (or recently neutropenic and still at high risk) patient represents a high-risk presentation requiring admission and empirical antibiotics, not discharge based on a single current temperature reading.', 2),
('da000000-0000-0000-0000-000000000019', 'C', 'Repeat the full blood count and wait for the result before deciding whether antibiotics are needed', false, 'Ruled out because the clinical history (documented fever, rigors, known recent neutropenia) is sufficient to warrant starting antibiotics without delay; waiting for a repeat blood count first risks dangerous delay in a potentially life-threatening presentation.', 3),
('da000000-0000-0000-0000-000000000019', 'D', 'Start oral antipyretics only and review in the outpatient oncology clinic within one week', false, 'Ruled out because this significantly under-treats a presentation consistent with neutropenic sepsis; urgent admission and IV antibiotics are required, not deferred outpatient review.', 4),
('da000000-0000-0000-0000-000000000019', 'E', 'Treat as a simple viral illness and manage supportively, since she is currently haemodynamically stable and afebrile', false, 'Ruled out because in a patient with recent chemotherapy and a neutrophil count in the neutropenic range, a documented fever with rigors must be treated as potential neutropenic sepsis until proven otherwise, given the risk of rapid deterioration; it should not be assumed to be a benign viral illness.', 5),
('da000000-0000-0000-0000-000000000020', 'A', 'Withhold corticosteroids until a formal short Synacthen (ACTH stimulation) test confirms adrenal insufficiency', false, 'Ruled out because in a suspected adrenal crisis, treatment with IV hydrocortisone should not be delayed for confirmatory testing; a random cortisol can be sent before the first dose if feasible, but treatment must proceed immediately given the life-threatening nature of untreated adrenal crisis.', 1),
('da000000-0000-0000-0000-000000000020', 'B', 'Treat as an adrenal (Addisonian) crisis with immediate intravenous hydrocortisone and aggressive fluid resuscitation, alongside urgent endocrinology input, while continuing to investigate the underlying immune-related hypophysitis/adrenalitis', true, 'Correct. This presentation (postural hypotension, hyponatraemia, hyperkalaemia, hypoglycaemia, low cortisol) in a patient on immune checkpoint inhibitor therapy represents an immune-related adverse event causing adrenal insufficiency (via hypophysitis affecting ACTH, or primary adrenalitis), presenting as an acute adrenal crisis. This is a medical emergency requiring immediate IV hydrocortisone (not waiting for confirmatory dynamic testing) and aggressive fluid resuscitation, with checkpoint inhibitor therapy typically paused during the acute crisis and long-term steroid replacement plus endocrinology follow-up arranged.', 2),
('da000000-0000-0000-0000-000000000020', 'C', 'Manage with oral fludrocortisone alone as the primary treatment for this presentation', false, 'Ruled out because acute adrenal crisis requires urgent IV (not oral) hydrocortisone and fluid resuscitation; fludrocortisone (mineralocorticoid replacement) is a longer-term consideration in primary adrenal insufficiency, not the acute emergency treatment, and is not typically needed if adequate hydrocortisone doses are used acutely.', 3),
('da000000-0000-0000-0000-000000000020', 'D', 'Attribute the presentation to axitinib-induced diarrhoea and dehydration and manage with oral rehydration salts alone', false, 'Ruled out because the biochemical picture (hyponatraemia, hyperkalaemia, hypoglycaemia, low cortisol) is specific for adrenal insufficiency/crisis, not simple dehydration from diarrhoea, and requires urgent steroid replacement, not oral rehydration alone.', 4),
('da000000-0000-0000-0000-000000000020', 'E', 'Continue pembrolizumab and axitinib unchanged while monitoring electrolytes, since endocrinopathies from immunotherapy are usually mild and self-limiting', false, 'Ruled out because immune-related adrenal insufficiency is a serious, potentially life-threatening endocrinopathy requiring urgent treatment and typically lifelong steroid replacement; it is not mild or self-limiting, and checkpoint inhibitor therapy should be paused during the acute crisis.', 5),
('da000000-0000-0000-0000-000000000021', 'A', 'Start urgent salvage chemotherapy at full standard doses to attempt to reduce hepatic tumour burden rapidly', false, 'Ruled out because standard-dose chemotherapy in the context of overt liver failure carries very high risk of severe, potentially fatal toxicity due to impaired hepatic drug clearance, with very low likelihood of meaningful benefit given the degree of hepatic replacement and failure already present.', 1),
('da000000-0000-0000-0000-000000000021', 'B', 'List for urgent liver transplantation given the severity of hepatic synthetic dysfunction', false, 'Ruled out because active metastatic malignancy involving the liver is a contraindication to liver transplantation; transplantation is not an appropriate option in this context.', 2),
('da000000-0000-0000-0000-000000000021', 'C', 'Perform urgent liver biopsy to confirm the diagnosis before any change in management approach', false, 'Ruled out because the diagnosis of malignant hepatic failure is already strongly supported by known metastatic disease and typical biochemical/clinical findings; an invasive biopsy in a patient with severe coagulopathy (INR 2.1) carries significant bleeding risk and would not change the fundamentally palliative direction of management.', 3),
('da000000-0000-0000-0000-000000000021', 'D', 'Focus on symptom-directed palliative management (including treatment of hepatic encephalopathy and coagulopathy as appropriate for comfort) and urgent discussion with the oncology team regarding prognosis and goals of care, since further systemic anti-cancer therapy is unlikely to be tolerated or beneficial in this setting', true, 'Correct. Extensive replacement of liver parenchyma by metastatic disease causing overt liver failure (jaundice, coagulopathy, encephalopathy) carries a very poor prognosis, typically measured in days to a few weeks, and further systemic chemotherapy is usually contraindicated because hepatic clearance of most cytotoxic and many targeted agents is severely impaired, risking fatal toxicity without meaningful anti-tumour benefit. The priority shifts to symptom control, encephalopathy/coagulopathy management for comfort, and honest, urgent discussion about prognosis and goals of care with the patient and family.', 4),
('da000000-0000-0000-0000-000000000021', 'E', 'Start lactulose and rifaximin for encephalopathy with the expectation that liver function will recover once ammonia is controlled', false, 'Ruled out because while lactulose/rifaximin can help symptomatically with encephalopathy as part of comfort-focused care, the underlying cause here is irreversible replacement of liver parenchyma by tumour, not a reversible metabolic derangement, so recovery of liver function should not be expected.', 5),
('da000000-0000-0000-0000-000000000022', 'A', 'Start a direct oral anticoagulant (DOAC, e.g. apixaban or rivaroxaban) as first-line treatment, following current cancer-associated thrombosis guidance, in the absence of gastrointestinal malignancy-related bleeding risk factors or significant drug interactions', true, 'Correct. Current guidance (reflecting major trials such as CARAVAGGIO, SELECT-D and Hokusai VTE Cancer) supports DOACs as a first-line option for most cancer-associated thrombosis, offering comparable or superior efficacy to low molecular weight heparin (LMWH) with the convenience of oral dosing, provided there is no high bleeding risk (e.g. luminal GI or urothelial cancers with intact primary, which favour LMWH due to higher DOAC-associated GI bleeding risk in some trials) and no significant drug-drug interactions.', 1),
('da000000-0000-0000-0000-000000000022', 'B', 'Start warfarin with an INR target of 2-3, as this remains the guideline-preferred agent for cancer-associated thrombosis', false, 'Ruled out because warfarin is no longer preferred for cancer-associated thrombosis due to inferior efficacy compared with LMWH/DOACs in this population and difficulty maintaining therapeutic INR alongside chemotherapy interactions and variable oral intake.', 2),
('da000000-0000-0000-0000-000000000022', 'C', 'Insert an inferior vena cava filter as first-line management instead of anticoagulation', false, 'Ruled out because IVC filters are reserved for specific situations such as absolute contraindication to anticoagulation or recurrent VTE despite adequate anticoagulation, not as first-line treatment when anticoagulation is not contraindicated.', 3),
('da000000-0000-0000-0000-000000000022', 'D', $x$Withhold anticoagulation entirely given the patient's active malignancy and instead manage with compression stockings alone$x$, false, 'Ruled out because active cancer with confirmed extensive DVT is a strong indication for anticoagulation (cancer itself does not contraindicate treatment); compression alone is inadequate and untreated proximal DVT carries high pulmonary embolism risk.', 4),
('da000000-0000-0000-0000-000000000022', 'E', 'Start unfractionated heparin infusion as the only appropriate first-line agent, reserving LMWH and DOACs for later once stable', false, 'Ruled out because unfractionated heparin infusion is not first-line for standard cancer-associated VTE management (typically reserved for specific situations such as severe renal impairment or need for rapid reversibility); DOACs or LMWH are the appropriate first-line choices here.', 5),
('da000000-0000-0000-0000-000000000023', 'A', 'Radiotherapy alone as the definitive treatment, given the presence of an epidural mass', false, 'Ruled out because radiotherapy alone is favoured when the tumour is highly radiosensitive, there is no significant instability, multiple levels are involved, or the patient has poor performance status/short prognosis — none of which fully apply here, whereas instability and relative radioresistance favour a surgical approach first.', 1),
('da000000-0000-0000-0000-000000000023', 'B', 'Chemotherapy alone as the definitive treatment, deferring both surgery and radiotherapy', false, 'Ruled out because chemotherapy has too slow an onset of action to be definitive treatment for cord compression, and does not address spinal instability; local treatment (surgery and/or radiotherapy) is required for this indication.', 2),
('da000000-0000-0000-0000-000000000023', 'C', 'Urgent surgical decompression and spinal stabilisation, followed by post-operative radiotherapy', true, 'Correct. Features favouring surgery over radiotherapy alone in malignant spinal cord compression include spinal instability, significant vertebral collapse/bony compression, a tumour type with lower radiosensitivity, single-level compression, good performance status and a longer estimated prognosis (>3-6 months) — all present here. Surgical decompression (e.g. with instrumented stabilisation) achieves better and faster neurological recovery than radiotherapy alone in this scenario, and post-operative radiotherapy is then given to consolidate local control.', 3),
('da000000-0000-0000-0000-000000000023', 'D', 'Vertebroplasty alone without decompressive surgery or radiotherapy', false, 'Ruled out because vertebroplasty addresses vertebral body pain/stability in the absence of cord compression but does not decompress an epidural mass causing neurological deficit; it is not an adequate treatment for active cord compression with significant neurological findings.', 4),
('da000000-0000-0000-0000-000000000023', 'E', 'Conservative management with analgesia and bed rest alone, given the severity of neurological deficit already present', false, 'Ruled out because conservative management without decompression or radiotherapy accepts permanent paraplegia in a patient with a reasonable prognosis and good performance status; active definitive treatment is indicated and achievable.', 5),
('da000000-0000-0000-0000-000000000024', 'A', 'Bacterial pneumonia; start empirical antibiotics alone and continue pembrolizumab unchanged', false, 'Ruled out because infective screening is negative and the clinical/radiological picture (bilateral ground-glass, subacute onset, no fever) is more consistent with immune-related pneumonitis; continuing pembrolizumab unchanged in the face of significant hypoxic pneumonitis risks serious deterioration.', 1),
('da000000-0000-0000-0000-000000000024', 'B', 'Immune checkpoint inhibitor-related pneumonitis; withhold pembrolizumab, start corticosteroid therapy, and admit for supportive care given the hypoxia', true, 'Correct. New bilateral ground-glass changes with dyspnoea and hypoxia in a patient on a PD-1 inhibitor, after excluding infection, is characteristic of checkpoint inhibitor pneumonitis, an immune-related adverse event. Grade 2 or higher pneumonitis (symptomatic, affecting daily activities, or with hypoxia as here) requires withholding the checkpoint inhibitor, prompt corticosteroid therapy, and admission for supportive care and monitoring given the risk of rapid respiratory deterioration; higher-grade or steroid-refractory cases may need additional immunosuppression (e.g. infliximab or mycophenolate) and permanent discontinuation of immunotherapy.', 2),
('da000000-0000-0000-0000-000000000024', 'C', 'Disease progression with lymphangitic carcinomatosis; continue pembrolizumab and arrange re-staging in 6 weeks', false, 'Ruled out because although disease progression is a differential for new pulmonary infiltrates, the acuity, bilateral peripheral ground-glass pattern and hypoxia in a patient on immunotherapy should prompt urgent consideration and treatment of pneumonitis rather than watchful waiting for a re-staging scan, which would delay necessary steroid treatment.', 3),
('da000000-0000-0000-0000-000000000024', 'D', 'Radiation pneumonitis; manage with inhaled bronchodilators alone, as this is a self-limiting condition', false, 'Ruled out because there is no mention of recent thoracic radiotherapy to support this diagnosis, and the described picture fits checkpoint inhibitor pneumonitis; bronchodilators alone would not address the underlying immune-mediated inflammation, which requires corticosteroids.', 4),
('da000000-0000-0000-0000-000000000024', 'E', 'Pulmonary embolism; start therapeutic anticoagulation empirically without further imaging', false, 'Ruled out because the CT findings described (bilateral ground-glass opacities) are not typical of pulmonary embolism, which would show filling defects on CT pulmonary angiography; the clinical and radiological pattern fits pneumonitis, and empirical anticoagulation without confirmatory imaging would not be appropriate here.', 5),
('da000000-0000-0000-0000-000000000025', 'A', 'Classify her as low-risk given normal renal function and start no specific tumour lysis prophylaxis', false, 'Ruled out because tumour burden, tumour type (high-grade lymphoma) and pre-existing subtle biochemical abnormalities are what determine risk, not renal function alone; normal creatinine does not equate to low risk in this context, and omitting prophylaxis would be unsafe.', 1),
('da000000-0000-0000-0000-000000000025', 'B', 'Start oral allopurinol only, as it is equally effective as rasburicase and preferred for cost reasons regardless of risk category', false, $x$Ruled out because allopurinol only prevents new urate formation and does not reduce existing urate, making it less effective than rasburicase in high-risk situations; allopurinol is more appropriate for lower-risk prophylaxis, and this patient's risk profile favours rasburicase.$x$, 2),
('da000000-0000-0000-0000-000000000025', 'C', 'Delay chemotherapy until all biochemical parameters are entirely normal', false, 'Ruled out because delaying essential chemotherapy for an aggressive high-grade lymphoma risks disease progression; the correct approach is to proceed with treatment under appropriate high-risk TLS prophylaxis, not to delay treatment.', 3),
('da000000-0000-0000-0000-000000000025', 'D', 'Restrict intravenous fluids prior to chemotherapy to avoid precipitating pulmonary oedema, relying on rasburicase alone', false, 'Ruled out because aggressive IV hydration (in the absence of contraindications such as pre-existing fluid overload or oliguric renal failure) is a core component of TLS prevention alongside urate-lowering therapy, not something to be withheld by default.', 4),
('da000000-0000-0000-0000-000000000025', 'E', 'Classify her as high-risk for tumour lysis syndrome given the bulky high-grade lymphoma and borderline biochemistry, and start prophylactic rasburicase with aggressive IV hydration before and during the first cycle of chemotherapy', true, 'Correct. High-grade lymphomas with high tumour burden and rapid proliferation carry a high inherent risk of tumour lysis syndrome, and this patient already has early laboratory abnormalities (mildly elevated urate, high-normal potassium, elevated phosphate) even before treatment. Risk stratification places her in a high-risk category, for which prophylactic rasburicase (rather than allopurinol) plus aggressive IV hydration is recommended, started before chemotherapy and continued through the peak lysis period (typically 24-72 hours after treatment) to prevent progression to established tumour lysis syndrome and its complications.', 5),
('da000000-0000-0000-0000-000000000026', 'A', 'Give intravenous furosemide to reduce venous congestion and reassess in 24 hours', false, 'Ruled out because diuretics reduce preload and can worsen haemodynamic compromise in tamponade, where adequate filling pressure is needed to maintain cardiac output against the compressive effusion; the priority is urgent drainage, not diuresis.', 1),
('da000000-0000-0000-0000-000000000026', 'B', 'Urgent pericardiocentesis (or surgical pericardial window) for drainage, with fluid sent for cytology, and consideration of a pericardial catheter/sclerosing agent or window to reduce recurrence risk', true, $x$Correct. This presentation — pulsus paradoxus, raised JVP with Kussmaul's sign, muffled heart sounds, hypotension, and echocardiographic evidence of diastolic RV collapse — confirms cardiac tamponade from a malignant pericardial effusion, a life-threatening emergency requiring urgent drainage (pericardiocentesis, ideally echo-guided, or a surgical pericardial window in select cases) to relieve the haemodynamic compromise. Fluid should be sent for cytology to confirm malignant involvement, and given the high recurrence rate of malignant effusions, an indwelling catheter, sclerosing agent, or formation of a pericardial window is often used to reduce recurrence.$x$, 2),
('da000000-0000-0000-0000-000000000026', 'C', 'Start high-dose corticosteroids as the primary treatment and reassess the effusion size in one week', false, 'Ruled out because corticosteroids do not provide the rapid mechanical relief required in tamponade; urgent pericardial drainage is the definitive emergency treatment, though steroids might have an adjunctive role in specific effusion aetiologies (e.g. lymphoma) once haemodynamics are stabilised.', 3),
('da000000-0000-0000-0000-000000000026', 'D', 'Manage conservatively with fluid restriction and observation, since the patient remains normotensive enough to tolerate a period of monitoring', false, 'Ruled out because the presence of pulsus paradoxus, hypotension trend, and echocardiographic RV diastolic collapse indicates haemodynamically significant tamponade requiring urgent intervention; observation alone risks rapid deterioration into cardiovascular collapse.', 4),
('da000000-0000-0000-0000-000000000026', 'E', 'Commence therapeutic anticoagulation to prevent thrombus formation within the pericardial space before drainage', false, 'Ruled out because anticoagulation is not indicated in the management of pericardial tamponade and would increase the risk of haemorrhagic complications during or after pericardiocentesis; there is no described indication for anticoagulation here.', 5),
('da000000-0000-0000-0000-000000000027', 'A', 'Myasthenia gravis associated with anti-acetylcholine receptor antibodies', false, 'Ruled out because myasthenia gravis classically causes fatigable weakness that worsens (not improves) with sustained activity, normal or preserved reflexes, and a decremental (not incremental) response on repetitive nerve stimulation — the opposite pattern to that described.', 1),
('da000000-0000-0000-0000-000000000027', 'B', 'Paraneoplastic cerebellar degeneration associated with anti-Yo antibodies', false, 'Ruled out because anti-Yo-associated cerebellar degeneration presents with ataxia, dysarthria and nystagmus rather than proximal weakness with autonomic features and the specific electrophysiological pattern described, and is more classically associated with ovarian/breast cancer, not lung cancer.', 2),
('da000000-0000-0000-0000-000000000027', 'C', 'Guillain-Barré syndrome with anti-GQ1b antibodies', false, 'Ruled out because Guillain-Barré syndrome typically presents with an acute, ascending, progressive weakness following an infective trigger with areflexia that does not improve with exertion, and anti-GQ1b antibodies are specifically associated with Miller Fisher syndrome (ataxia, areflexia, ophthalmoplegia), not this presentation.', 3),
('da000000-0000-0000-0000-000000000027', 'D', 'Lambert-Eaton myasthenic syndrome associated with antibodies against voltage-gated calcium channels (VGCC), most commonly paraneoplastic to small cell lung cancer', true, 'Correct. This presentation — proximal weakness improving with exercise (post-tetanic facilitation), autonomic symptoms (dry mouth, erectile dysfunction), reduced reflexes that potentiate after exertion, and incremental response on high-frequency repetitive nerve stimulation — is classic for Lambert-Eaton myasthenic syndrome (LEMS), caused by antibodies against presynaptic voltage-gated calcium channels impairing acetylcholine release. LEMS is strongly associated with small cell lung cancer, and the underlying malignancy should always be actively sought and treated, often improving the neurological syndrome.', 4),
('da000000-0000-0000-0000-000000000027', 'E', 'Polymyositis associated with anti-Jo-1 antibodies', false, 'Ruled out because polymyositis causes symmetrical proximal weakness without the exercise-induced improvement, autonomic symptoms, or characteristic incremental repetitive nerve stimulation response described, and anti-Jo-1 antibodies are linked to antisynthetase syndrome, a distinct clinical entity.', 5),
('da000000-0000-0000-0000-000000000028', 'A', 'Small cell lung cancer; arrange urgent CT chest as the priority investigation', false, 'Ruled out because small cell lung cancer is classically associated with anti-Hu (ANNA-1) antibodies (causing a broader paraneoplastic encephalomyelitis/sensory neuronopathy) and Lambert-Eaton myasthenic syndrome (anti-VGCC), not anti-Yo; while lung imaging may still be considered as part of a broad search, ovarian/breast malignancy is the priority given the anti-Yo result.', 1),
('da000000-0000-0000-0000-000000000028', 'B', 'Testicular germ cell tumour; arrange scrotal ultrasound as the priority investigation', false, $x$Ruled out because testicular tumours are associated with anti-Ma2 antibody syndromes (causing limbic/diencephalic/brainstem encephalitis), not anti-Yo-associated cerebellar degeneration, and this patient's sex/antibody profile does not fit this association.$x$, 2),
('da000000-0000-0000-0000-000000000028', 'C', 'Ovarian or breast carcinoma; arrange pelvic imaging (CT/MRI or transvaginal ultrasound) and mammography as priority investigations', true, 'Correct. Anti-Yo (PCA-1) antibody-associated paraneoplastic cerebellar degeneration is most strongly linked to gynaecological malignancies (particularly ovarian carcinoma) and breast cancer. The onset of a rapidly progressive cerebellar syndrome should prompt urgent, targeted investigation for these cancers even when routine screening has previously been normal, as the neurological syndrome frequently precedes overt cancer diagnosis, and early cancer treatment offers the best chance of neurological stabilisation.', 3),
('da000000-0000-0000-0000-000000000028', 'D', 'Renal cell carcinoma; arrange CT abdomen and pelvis with contrast as the priority investigation', false, 'Ruled out because renal cell carcinoma is not a classic association for anti-Yo antibody syndrome; the strong, well-established link is with ovarian and breast malignancy, which should be prioritised.', 4),
('da000000-0000-0000-0000-000000000028', 'E', 'Thymoma; arrange CT chest with mediastinal windows as the priority investigation', false, 'Ruled out because thymoma is classically associated with myasthenia gravis and some other neuromuscular paraneoplastic syndromes, not anti-Yo cerebellar degeneration, which points specifically towards gynaecological or breast malignancy.', 5),
('da000000-0000-0000-0000-000000000029', 'A', 'PTHrP secreted by the tumour binds PTH receptors, mimicking PTH action to increase bone resorption and renal calcium reabsorption, causing humoral hypercalcaemia of malignancy', true, 'Correct. Humoral hypercalcaemia of malignancy, most classically associated with squamous cell carcinomas (lung, head and neck, oesophagus, cervix) as well as renal and bladder cancers, is caused by tumour secretion of PTH-related peptide (PTHrP), which binds the same PTH receptor and mimics its effects on bone (increasing resorption) and kidney (increasing calcium reabsorption and reducing phosphate reabsorption), while appropriately suppressing endogenous PTH via negative feedback on the parathyroid glands.', 1),
('da000000-0000-0000-0000-000000000029', 'B', 'Direct osteolytic bone metastases releasing calcium locally are responsible, independent of any humoral factor', false, $x$Ruled out because although osteolytic metastases can cause hypercalcaemia (e.g. in myeloma, breast cancer), this patient's markedly elevated PTHrP with suppressed PTH indicates a humoral mechanism rather than (or in addition to) local osteolysis, and the two mechanisms are distinguished by PTHrP levels.$x$, 2),
('da000000-0000-0000-0000-000000000029', 'C', 'Excess 1,25-dihydroxyvitamin D (calcitriol) production by tumour-associated macrophages is the primary mechanism', false, $x$Ruled out because calcitriol-mediated hypercalcaemia is classically associated with lymphomas (via ectopic 1-alpha-hydroxylase activity in tumour-associated macrophages), not squamous cell lung cancer, and this patient's picture is explained by elevated PTHrP, not vitamin D dysregulation.$x$, 3),
('da000000-0000-0000-0000-000000000029', 'D', 'Ectopic parathyroid hormone (PTH) secretion directly by the tumour is responsible for the hypercalcaemia', false, 'Ruled out because true ectopic PTH secretion by tumours is extremely rare; the PTH level here is appropriately suppressed (not elevated), consistent with PTHrP-mediated humoral hypercalcaemia rather than ectopic PTH production.', 4),
('da000000-0000-0000-0000-000000000029', 'E', 'Immobility-related bone resorption from reduced mobility due to cancer-related fatigue is the primary cause', false, 'Ruled out because although immobility can contribute to hypercalcaemia in some contexts, the markedly elevated PTHrP with suppressed PTH specifically indicates a humoral paraneoplastic mechanism as the primary driver here, not simple immobility.', 5),
('da000000-0000-0000-0000-000000000030', 'A', 'Immediate hypertonic (3%) saline infusion given the degree of hyponatraemia, regardless of symptom severity', false, 'Ruled out because hypertonic saline is reserved for severe, symptomatic hyponatraemia (e.g. seizures, severe confusion, coma), not for a patient who is only mildly symptomatic (nausea) despite a low sodium value; using it here risks overly rapid correction and osmotic demyelination.', 1),
('da000000-0000-0000-0000-000000000030', 'B', 'Fluid restriction is contraindicated in cancer-associated SIADH; free water administration should instead be encouraged to prevent dehydration', false, 'Ruled out because this is the opposite of correct management — encouraging free water intake would worsen the hyponatraemia in SIADH; fluid restriction is the appropriate first-line strategy.', 2),
('da000000-0000-0000-0000-000000000030', 'C', 'Start high-dose corticosteroids as first-line treatment for paraneoplastic SIADH', false, 'Ruled out because corticosteroids are not a standard treatment for SIADH (they are relevant to excluding adrenal insufficiency as a differential, which has been excluded here); fluid restriction and treating the underlying cancer are the mainstays of management.', 3),
('da000000-0000-0000-0000-000000000030', 'D', 'Administer intravenous 0.9% normal saline as first-line treatment to correct the sodium', false, 'Ruled out because in true SIADH, 0.9% saline can paradoxically worsen hyponatraemia (as the retained free water from the relatively hypotonic urine excreted exceeds the sodium retained), making fluid restriction the preferred initial approach rather than isotonic saline.', 4),
('da000000-0000-0000-0000-000000000030', 'E', 'Fluid restriction as first-line management, with close monitoring of sodium correction rate to avoid overly rapid correction, alongside treatment of the underlying malignancy', true, 'Correct. This presentation is consistent with paraneoplastic SIADH from small cell lung cancer (ectopic ADH secretion), confirmed by euvolaemic hyponatraemia with inappropriately concentrated urine, elevated urine sodium, and exclusion of other causes (renal, thyroid, adrenal). In an asymptomatic or mildly symptomatic patient, fluid restriction is the first-line treatment, with careful monitoring to avoid correcting sodium too rapidly (risk of osmotic demyelination syndrome); treatment of the underlying cancer with chemotherapy often improves the SIADH as tumour burden reduces.', 5),
('da000000-0000-0000-0000-000000000031', 'A', 'Reassure the patient that dermatomyositis has no significant malignancy association and proceed with immunosuppression alone', false, 'Ruled out because dermatomyositis carries a well-established, clinically important association with occult malignancy, and failing to screen risks missing a treatable underlying cancer.', 1),
('da000000-0000-0000-0000-000000000031', 'B', 'Arrange age- and sex-appropriate malignancy screening (including gynaecological, breast, and other relevant age-appropriate cancer screening) given the recognised association between dermatomyositis and underlying malignancy, in addition to starting immunosuppressive treatment for the myositis', true, 'Correct. Dermatomyositis (more so than polymyositis) has a well-recognised association with underlying malignancy, particularly ovarian, lung, pancreatic, gastric, colorectal and lymphoma in adults, with risk highest around the time of diagnosis and for the following 1-3 years. Comprehensive age- and sex-appropriate malignancy screening (beyond routine population screening, often including CT chest/abdomen/pelvis and CA-125/pelvic ultrasound in women) should be arranged at diagnosis, alongside starting treatment (typically corticosteroids +/- steroid-sparing agents) for the myositis itself.', 2),
('da000000-0000-0000-0000-000000000031', 'C', 'Defer any malignancy screening for at least 12 months, as cancer risk in dermatomyositis is not increased in the initial period after diagnosis', false, 'Ruled out because the risk of underlying malignancy is in fact highest around the time of dermatomyositis diagnosis, so screening should be undertaken promptly, not deferred.', 3),
('da000000-0000-0000-0000-000000000031', 'D', 'Screen only for lung cancer, as this is the sole malignancy associated with dermatomyositis', false, 'Ruled out because dermatomyositis is associated with multiple malignancy types (ovarian, lung, pancreatic, gastric, colorectal, lymphoma, among others), so a broader, comprehensive screen is required rather than focusing on a single cancer type.', 4),
('da000000-0000-0000-0000-000000000031', 'E', 'Withhold immunosuppressive treatment for the myositis until malignancy screening is fully completed', false, 'Ruled out because treatment of significant, potentially disabling myositis should not be delayed pending completion of malignancy screening; the two processes (treating the myositis and searching for an underlying cancer) proceed in parallel.', 5),
('da000000-0000-0000-0000-000000000032', 'A', 'Elevated PTH level, similar to that seen in primary hyperparathyroidism', false, 'Ruled out because in PTHrP-mediated humoral hypercalcaemia of malignancy, endogenous PTH is suppressed (not elevated) due to negative feedback from hypercalcaemia; an elevated PTH would instead suggest primary (or less commonly tertiary) hyperparathyroidism.', 1),
('da000000-0000-0000-0000-000000000032', 'B', 'Elevated urinary calcium excretion identical in magnitude between the two conditions, providing no diagnostic value', false, 'Ruled out because although both conditions can cause increased urinary calcium excretion, this does not reliably differentiate the two conditions from each other, unlike PTH and calcitriol levels, which do provide useful discrimination.', 2),
('da000000-0000-0000-0000-000000000032', 'C', 'Low serum calcium with normal phosphate, typical of both conditions', false, 'Ruled out because both PTHrP-mediated hypercalcaemia and primary hyperparathyroidism cause elevated (not low) serum calcium with low (not normal) phosphate; this option misdescribes the expected biochemistry of both conditions.', 3),
('da000000-0000-0000-0000-000000000032', 'D', 'Low or low-normal 1,25-dihydroxyvitamin D (calcitriol) level, in contrast to the typically elevated or high-normal calcitriol seen in primary hyperparathyroidism', true, 'Correct. Although both PTHrP-mediated humoral hypercalcaemia of malignancy and primary hyperparathyroidism cause hypercalcaemia with hypophosphataemia (via reduced renal phosphate reabsorption) and can appear biochemically similar at first glance, calcitriol (1,25-dihydroxyvitamin D) levels differ: PTH stimulates renal 1-alpha-hydroxylase leading to elevated calcitriol in primary hyperparathyroidism, whereas PTHrP is a less potent stimulator of this enzyme, so calcitriol is typically low or low-normal in humoral hypercalcaemia of malignancy — this, alongside a suppressed PTH level (the key initial discriminator), helps confirm the diagnosis.', 4),
('da000000-0000-0000-0000-000000000032', 'E', 'Elevated serum magnesium levels in both conditions, providing the key distinguishing feature', false, 'Ruled out because magnesium is not the key discriminating biochemical feature between these two causes of hypercalcaemia; PTH and calcitriol levels are the relevant distinguishing investigations.', 5),
('da000000-0000-0000-0000-000000000033', 'A', 'Small cell lung cancer; arrange urgent CT chest as the priority investigation, with immunotherapy deferred until a tumour is identified', false, 'Ruled out because although SCLC can rarely be associated with anti-NMDA receptor encephalitis (more so in older patients or men), ovarian teratoma is the classic and most important association, particularly in this age group and sex; more importantly, immunotherapy should never be deferred pending tumour identification given the risk of rapid deterioration.', 1),
('da000000-0000-0000-0000-000000000033', 'B', 'Thymoma; arrange CT chest with mediastinal windows as the priority investigation', false, 'Ruled out because thymoma is not the characteristic tumour association for anti-NMDA receptor encephalitis; ovarian teratoma is the classic association, particularly in young women.', 2),
('da000000-0000-0000-0000-000000000033', 'C', 'Ovarian teratoma; arrange pelvic imaging (MRI or transvaginal ultrasound) urgently, and start first-line immunotherapy (e.g. high-dose corticosteroids, IVIG or plasma exchange) without waiting for tumour identification, since tumour removal alongside immunotherapy improves outcomes', true, 'Correct. Anti-NMDA receptor encephalitis, particularly in women of reproductive age, has a strong association with ovarian teratoma, which should be actively and urgently sought via pelvic imaging. Regardless of whether a tumour is found, first-line immunotherapy (corticosteroids, IVIG, and/or plasma exchange) should be started promptly given the potentially severe and life-threatening course of this encephalitis; when a teratoma is identified, its surgical removal is an important part of treatment and improves the chance of neurological recovery, often combined with ongoing immunotherapy.', 3),
('da000000-0000-0000-0000-000000000033', 'D', $x$Testicular germ cell tumour; arrange scrotal ultrasound, which is not applicable given the patient's sex$x$, false, 'Ruled out because this option is anatomically inapplicable to a female patient and reflects the wrong tumour association; ovarian teratoma (the female-specific counterpart in terms of tumour biology) is the relevant association here.', 4),
('da000000-0000-0000-0000-000000000033', 'E', 'No underlying tumour association exists for anti-NMDA receptor encephalitis, so no specific malignancy screening is required', false, 'Ruled out because anti-NMDA receptor encephalitis has a well-established and clinically important association with ovarian teratoma, particularly in women of reproductive age, and active screening is an essential part of management.', 5),
('da000000-0000-0000-0000-000000000034', 'A', 'Reassure the patient that his cancer history is unrelated, as remission for two years excludes recurrence as a cause', false, 'Ruled out because a positive anti-Hu antibody with a new compatible neurological syndrome should raise strong suspicion for cancer recurrence regardless of the duration of prior remission, and this possibility must be actively investigated, not dismissed.', 1),
('da000000-0000-0000-0000-000000000034', 'B', 'Start empirical antiviral therapy for presumed viral cerebellitis without further oncological investigation', false, 'Ruled out because the clinical and serological picture (positive anti-Hu antibody, prior SCLC) strongly suggests a paraneoplastic rather than infective aetiology; oncological restaging is the priority, not antiviral therapy.', 2),
('da000000-0000-0000-0000-000000000034', 'C', 'Proceed directly to cerebellar biopsy to confirm the diagnosis before considering any oncological investigations', false, 'Ruled out because brain biopsy is not required or appropriate here; the diagnosis is supported by the clinical syndrome and antibody positivity, and the priority is systemic restaging to detect potential cancer recurrence, not invasive cerebral tissue sampling.', 3),
('da000000-0000-0000-0000-000000000034', 'D', 'Manage with high-dose corticosteroids alone as definitive treatment, without further investigation for malignancy', false, 'Ruled out because while immunotherapy may be considered for the neurological syndrome, the essential and urgent step is to investigate for underlying/recurrent malignancy, since treating the cancer (if found) offers the best chance of stabilising the paraneoplastic syndrome, and missing a recurrence would be a significant omission.', 4),
('da000000-0000-0000-0000-000000000034', 'E', 'Arrange urgent restaging investigations (e.g. CT chest/abdomen/pelvis, consider PET-CT) to look for recurrence of the small cell lung cancer or a new primary, given the strong association between anti-Hu antibodies and this malignancy', true, 'Correct. Anti-Hu (ANNA-1) antibody-positive paraneoplastic syndromes (which can include cerebellar degeneration, sensory neuronopathy, and limbic encephalitis) are strongly associated with small cell lung cancer. A new anti-Hu-positive neurological syndrome in a patient with a prior history of SCLC, even in previous remission, should prompt urgent restaging to look for disease recurrence, as the paraneoplastic syndrome can be the first clinical sign of relapse, sometimes preceding radiological detection by conventional means.', 5),
('da000000-0000-0000-0000-000000000035', 'A', 'Stauffer syndrome — a paraneoplastic hepatic dysfunction associated with renal cell carcinoma, mediated by cytokine release (e.g. IL-6) rather than hepatic metastatic infiltration', true, 'Correct. Stauffer syndrome is a paraneoplastic phenomenon seen in renal cell carcinoma characterised by cholestatic liver dysfunction (raised ALP/GGT) in the absence of hepatic metastases, thought to be mediated by tumour cytokine production (particularly IL-6) causing reversible hepatic dysfunction, often accompanied by systemic symptoms (fever, weight loss, malaise) and raised inflammatory markers. It typically resolves with successful treatment of the underlying renal cell carcinoma (e.g. nephrectomy) and its recognition avoids unnecessary extensive additional hepatic investigation.', 1),
('da000000-0000-0000-0000-000000000035', 'B', 'Occult hepatic metastases not visible on current imaging; arrange liver biopsy to confirm metastatic infiltration', false, 'Ruled out because although metastases should always be considered, the classic combination of cholestatic LFTs with systemic inflammatory features and no metastases on adequate imaging in RCC is characteristic of Stauffer syndrome, a recognised paraneoplastic phenomenon, making an assumption of occult metastasis (and an invasive biopsy) premature without first considering this diagnosis.', 2),
('da000000-0000-0000-0000-000000000035', 'C', 'Drug-induced liver injury from recent systemic anti-cancer therapy; stop all current treatment immediately', false, 'Ruled out because no specific hepatotoxic drug exposure is described, and the combination of systemic B symptoms with cholestatic LFTs in the context of RCC is more consistent with a recognised paraneoplastic syndrome (Stauffer syndrome) than drug-induced injury, though medication review remains reasonable practice generally.', 3),
('da000000-0000-0000-0000-000000000035', 'D', 'Primary biliary cholangitis coincidentally presenting alongside his cancer diagnosis; arrange anti-mitochondrial antibody testing as the priority investigation', false, 'Ruled out because while autoimmune liver disease could theoretically coincide, the clinical context (renal cell carcinoma with systemic symptoms and cholestatic LFTs without metastases) makes Stauffer syndrome the far more likely and clinically relevant explanation to consider first.', 4),
('da000000-0000-0000-0000-000000000035', 'E', 'Sepsis from an occult intra-abdominal source; arrange further cross-sectional imaging and empirical antibiotics', false, 'Ruled out because the vignette specifies an extensive infective workup has already been negative, making Stauffer syndrome the more likely unifying diagnosis rather than continuing to pursue an infective source.', 5),
('da000000-0000-0000-0000-000000000036', 'A', 'Age-related macular degeneration; arrange routine ophthalmology follow-up with no further oncological investigation needed', false, 'Ruled out because the electroretinographic findings, positive anti-recoverin antibody, and prior cancer history strongly suggest a paraneoplastic retinopathy rather than age-related macular degeneration, and this requires urgent (not routine) oncological restaging given the recurrence risk implication.', 1),
('da000000-0000-0000-0000-000000000036', 'B', 'Diabetic retinopathy secondary to undiagnosed diabetes; arrange HbA1c testing as the priority investigation', false, 'Ruled out because there is no mention of diabetic risk factors, and diabetic retinopathy would typically show characteristic fundoscopic changes (microaneurysms, haemorrhages) rather than a normal fundus with markedly abnormal electroretinography; the clinical picture here fits a paraneoplastic process.', 2),
('da000000-0000-0000-0000-000000000036', 'C', 'Retinal detachment; arrange emergency ophthalmology referral for surgical repair', false, 'Ruled out because retinal detachment would typically present with sudden visual field loss and characteristic fundoscopic findings, not the gradual bilateral photoreceptor dysfunction with reduced ERG response and positive paraneoplastic antibody described here.', 3),
('da000000-0000-0000-0000-000000000036', 'D', 'Chloroquine or hydroxychloroquine-induced retinal toxicity; stop the relevant medication urgently', false, 'Ruled out because there is no history of hydroxychloroquine or chloroquine use provided in the vignette, making this an irrelevant distractor rather than the diagnosis suggested by the antibody and ERG findings.', 4),
('da000000-0000-0000-0000-000000000036', 'E', 'Cancer-associated retinopathy; arrange urgent restaging investigations to look for recurrent breast cancer or a new malignancy, alongside ophthalmology and consideration of immunosuppressive therapy', true, 'Correct. Cancer-associated retinopathy (CAR), associated with anti-recoverin antibodies among others, is a rare paraneoplastic syndrome causing progressive visual loss, photopsia and reduced photoreceptor function on electroretinography, often with a relatively normal-appearing fundus, particularly early on. It is most classically linked to small cell lung cancer but also occurs with breast and gynaecological cancers; a new diagnosis in a patient with a cancer history should prompt urgent restaging for recurrence, alongside specialist ophthalmology input and consideration of immunosuppressive treatment (e.g. corticosteroids, IVIG) to try to preserve vision, which can otherwise progress to severe, irreversible loss.', 5),
('da000000-0000-0000-0000-000000000037', 'A', 'Primary hyperaldosteronism from an adrenal adenoma; arrange adrenal vein sampling as the priority investigation before any treatment', false, $x$Ruled out because the markedly elevated cortisol with failure to suppress on high-dose dexamethasone, in the context of small cell lung cancer, points to ectopic ACTH-driven Cushing's syndrome rather than primary hyperaldosteronism, and the immediate priority is correcting life-threatening hypokalaemia and reducing cortisol, not further localisation imaging before any treatment.$x$, 1),
('da000000-0000-0000-0000-000000000037', 'B', $x$Pituitary-dependent Cushing's disease; arrange pituitary MRI and consider transsphenoidal surgery as the definitive treatment$x$, false, $x$Ruled out because pituitary Cushing's disease typically shows partial suppression with high-dose dexamethasone (unlike the complete failure to suppress seen with ectopic ACTH sources) and a more gradual onset with more prominent classic centripetal features; the rapid onset and biochemical severity here, combined with known SCLC, favour an ectopic source.$x$, 2),
('da000000-0000-0000-0000-000000000037', 'C', $x$Conn's syndrome secondary to a co-existing adrenal adenoma; start spironolactone as first-line treatment without addressing cortisol levels$x$, false, $x$Ruled out because spironolactone addresses aldosterone-mediated potassium wasting, not the underlying cortisol excess driving this presentation, and would not adequately address the severity or the underlying pathophysiology of ectopic ACTH-driven Cushing's syndrome.$x$, 3),
('da000000-0000-0000-0000-000000000037', 'D', $x$Ectopic ACTH secretion by the tumour causing Cushing's syndrome; the immediate priority is correction of the severe hypokalaemia and metabolic alkalosis, alongside rapid cortisol-lowering therapy (e.g. metyrapone or ketoconazole) while definitive treatment of the underlying cancer is arranged$x$, true, $x$Correct. Ectopic ACTH secretion, most classically from small cell lung cancer (and bronchial carcinoid), causes a rapidly progressive Cushing's syndrome with a characteristic biochemical picture of severe hypokalaemia and metabolic alkalosis (due to very high cortisol levels overwhelming 11-beta-hydroxysteroid dehydrogenase and exerting mineralocorticoid effects), often with less of the classic centripetal weight gain seen in pituitary-driven Cushing's disease due to the rapidity of onset. Failure to suppress with high-dose dexamethasone supports an ectopic (non-pituitary) ACTH source. The severe hypokalaemia is immediately life-threatening (arrhythmia risk) and must be corrected urgently, alongside rapid medical reduction of cortisol synthesis (e.g. metyrapone, ketoconazole) while definitive oncological treatment is arranged, as surgery is rarely feasible for the primary source in this setting.$x$, 4),
('da000000-0000-0000-0000-000000000037', 'E', 'Factitious hypokalaemia from diuretic misuse; take a further collateral history and defer any specific treatment', false, 'Ruled out because the combination of markedly elevated cortisol failing to suppress with dexamethasone, rapid-onset myopathy/plethora, and known small cell lung cancer strongly supports ectopic ACTH syndrome as an organic diagnosis, not factitious diuretic use, and urgent treatment (not deferral) is required given the severity of hypokalaemia.', 5),
('da000000-0000-0000-0000-000000000038', 'A', 'Rheumatoid arthritis with incidental lung nodule; start disease-modifying antirheumatic drug (DMARD) therapy and monitor the lung mass conservatively', false, 'Ruled out because the combination of clubbing, symmetrical periosteal new bone formation on imaging, and a large lung mass is characteristic of HPOA secondary to malignancy, not rheumatoid arthritis (which does not typically cause clubbing or this radiographic periosteal pattern); the lung mass requires urgent, not conservative, investigation.', 1),
('da000000-0000-0000-0000-000000000038', 'B', 'Primary hypertrophic osteoarthropathy (pachydermoperiostosis), an inherited condition unrelated to the lung mass, requiring no further oncological investigation', false, 'Ruled out because primary (inherited) hypertrophic osteoarthropathy typically presents in younger patients, often with a family history and characteristic skin changes (pachydermia), and the presence of a large lung mass in an older smoker makes secondary HPOA due to malignancy far more likely, requiring urgent investigation of the mass.', 2),
('da000000-0000-0000-0000-000000000038', 'C', 'Hypertrophic pulmonary osteoarthropathy (HPOA) secondary to underlying lung malignancy; arrange staging investigations and histological confirmation of the lung mass as the priority', true, 'Correct. Hypertrophic pulmonary osteoarthropathy is a paraneoplastic syndrome characterised by digital clubbing, symmetrical polyarthritis-like joint pain/swelling, and periosteal new bone formation (classically affecting the distal long bones such as the tibia, fibula, radius and ulna), most commonly associated with non-small cell lung cancer (particularly adenocarcinoma) and occasionally other intrathoracic malignancies or mesothelioma. Identification of this syndrome in a patient with a lung mass should prompt urgent staging and tissue diagnosis of the underlying cancer, as HPOA symptoms often improve or resolve following successful treatment of the primary tumour.', 3),
('da000000-0000-0000-0000-000000000038', 'D', 'Gout affecting multiple joints; start urate-lowering therapy and defer further investigation of the lung mass', false, 'Ruled out because the described pattern (clubbing, symmetrical periosteal new bone formation on imaging) is not typical of gout, and a large lung mass found incidentally must be urgently investigated regardless of joint symptoms, not deferred.', 4),
('da000000-0000-0000-0000-000000000038', 'E', 'Metastatic bone disease directly infiltrating the tibiae and fibulae bilaterally, requiring urgent bone biopsy of the legs before any other investigation', false, 'Ruled out because the radiographic description (symmetrical periosteal new bone formation along the shafts) is characteristic of reactive periostitis in HPOA rather than direct osteolytic/osteoblastic metastatic infiltration, and the priority is diagnosing and staging the underlying lung mass, not biopsying the legs first.', 5),
('da000000-0000-0000-0000-000000000039', 'A', 'Risk-reducing bilateral salpingo-oophorectomy, typically recommended after completion of childbearing and around age 35-40 for BRCA1 carriers', true, 'Correct. For BRCA1 mutation carriers, risk-reducing bilateral salpingo-oophorectomy (RRSO) is the most effective strategy for reducing ovarian cancer risk and mortality, as ovarian cancer screening (CA-125 and transvaginal ultrasound) has not been shown to reliably reduce mortality due to the aggressive nature and often late detection of BRCA-associated ovarian cancers even with surveillance. RRSO is generally recommended around age 35-40 for BRCA1 carriers (slightly later, around 40-45, for BRCA2) once childbearing is complete, and also reduces breast cancer risk somewhat via reduced oestrogen exposure.', 1),
('da000000-0000-0000-0000-000000000039', 'B', 'Annual CA-125 blood testing and transvaginal ultrasound as a definitive alternative to surgery, providing equivalent mortality reduction', false, 'Ruled out because CA-125/ultrasound-based ovarian cancer screening has not been shown to reduce ovarian cancer mortality in BRCA carriers to the degree that RRSO achieves, due to the aggressive tumour biology and limited sensitivity for early-stage detection; it may be used as an interim strategy before RRSO but is not equivalent to surgery.', 2),
('da000000-0000-0000-0000-000000000039', 'C', 'Prophylactic hysterectomy alone without removal of the fallopian tubes and ovaries', false, 'Ruled out because hysterectomy alone does not address ovarian/fallopian tube cancer risk, which is the predominant gynaecological cancer risk conferred by BRCA1 mutations; RRSO (removal of tubes and ovaries) is required for this risk reduction.', 3),
('da000000-0000-0000-0000-000000000039', 'D', 'Chemoprevention with tamoxifen alone, without consideration of surgical risk reduction', false, 'Ruled out because tamoxifen is a chemopreventive option relevant to breast cancer risk reduction, not ovarian cancer risk reduction, and does not substitute for RRSO in reducing ovarian cancer mortality in BRCA1 carriers.', 4),
('da000000-0000-0000-0000-000000000039', 'E', 'Reassurance that no risk-reducing intervention is required until symptoms of ovarian cancer develop', false, 'Ruled out because BRCA1 carriers have a substantially elevated lifetime ovarian cancer risk (up to ~40-50%), and proactive risk-reducing surgery, not a watch-and-wait approach, is recommended given the poor performance of symptom-based or screening-based early detection in this population.', 5),
('da000000-0000-0000-0000-000000000040', 'A', 'Reassure the patient and continue routine three-monthly CEA monitoring without further imaging, as CEA can fluctuate for benign reasons', false, 'Ruled out because a consistent, progressive rise in CEA (not an isolated fluctuation) across three separate measurements is a significant and specific pattern warranting active further investigation rather than reassurance and continued passive monitoring alone.', 1),
('da000000-0000-0000-0000-000000000040', 'B', 'Arrange repeat cross-sectional imaging (CT chest/abdomen/pelvis) and consider PET-CT if this remains negative, given the progressively rising CEA trend despite recent normal imaging', true, 'Correct. A progressive, rising trend in CEA (rather than an isolated single elevated value) after curative treatment for colorectal cancer is highly suggestive of disease recurrence, even when recent standard cross-sectional imaging was normal, since recurrence can be occult on CT alone in its early stages. Repeat, updated cross-sectional imaging is the first step, and PET-CT has higher sensitivity for detecting small-volume or occult recurrent disease and should be considered if repeat CT remains unremarkable, to guide further management (e.g. potential resection of oligometastatic disease).', 2),
('da000000-0000-0000-0000-000000000040', 'C', 'Diagnose disease recurrence definitively based on the CEA trend alone and refer directly for palliative chemotherapy without further imaging', false, 'Ruled out because CEA elevation alone, without radiological or pathological confirmation of recurrent/metastatic disease, is not sufficient to definitively diagnose recurrence or to commit to a treatment pathway; imaging to localise and characterise any recurrence is required first.', 3),
('da000000-0000-0000-0000-000000000040', 'D', 'Repeat colonoscopy alone, as this is the only investigation needed to explain a rising CEA after colorectal cancer treatment', false, 'Ruled out because a recent colonoscopy was already normal, and rising CEA in this context is more likely to reflect extraluminal/metastatic recurrence (e.g. liver, lung, peritoneal) than a local luminal recurrence that colonoscopy would detect; cross-sectional imaging is the appropriate next investigation.', 4),
('da000000-0000-0000-0000-000000000040', 'E', 'Stop CEA monitoring altogether, as it is not considered clinically useful in colorectal cancer surveillance', false, 'Ruled out because CEA is a recommended, useful surveillance tool in resected colorectal cancer specifically because a rising trend, as demonstrated here, can be an early indicator of recurrence prompting further investigation.', 5),
('da000000-0000-0000-0000-000000000041', 'A', 'Mixed germ cell tumour with yolk sac elements, since AFP elevation is inconsistent with this diagnosis', false, 'Ruled out because AFP elevation is in fact characteristic of yolk sac tumour components; this option incorrectly excludes the diagnosis most consistent with the marker pattern rather than the one that is truly excluded (pure seminoma).', 1),
('da000000-0000-0000-0000-000000000041', 'B', 'Pure seminoma, since AFP elevation is never seen in pure seminoma and its presence indicates either a non-seminomatous component or mixed germ cell tumour', true, 'Correct. Alpha-fetoprotein is never produced by pure seminoma; its elevation, even in a tumour with some seminomatous morphology on biopsy, indicates the presence of non-seminomatous elements (e.g. yolk sac tumour component) and mandates that the tumour be managed as a non-seminomatous germ cell tumour (NSGCT), which has different management and prognostic implications than pure seminoma. Beta-hCG can be mildly elevated in a minority of pure seminomas (from syncytiotrophoblastic giant cells) but AFP elevation is specific for a non-seminomatous component.', 2),
('da000000-0000-0000-0000-000000000041', 'C', 'Choriocarcinoma, since beta-hCG elevation is inconsistent with this diagnosis', false, 'Ruled out because choriocarcinoma classically causes marked beta-hCG elevation (from syncytiotrophoblastic cells), making this the opposite of an excluded diagnosis; this marker pattern would not exclude choriocarcinoma.', 3),
('da000000-0000-0000-0000-000000000041', 'D', 'Embryonal carcinoma, since neither AFP nor beta-hCG is ever elevated in this subtype', false, 'Ruled out because embryonal carcinoma can be associated with elevations in both AFP and beta-hCG depending on component cell types, so this statement is incorrect, and embryonal carcinoma is not excluded by this marker pattern.', 4),
('da000000-0000-0000-0000-000000000041', 'E', 'Leydig cell tumour, since AFP and beta-hCG are the specific markers for this diagnosis', false, 'Ruled out because Leydig cell tumours are sex cord-stromal tumours that do not typically produce AFP or beta-hCG; they may cause hormonal effects (e.g. gynaecomastia from oestrogen production) but are not associated with these markers, and this option misattributes the marker pattern.', 5),
('da000000-0000-0000-0000-000000000042', 'A', 'Type 2 diabetes mellitus; this is the most important benign cause of CA-125 elevation to consider in clinical practice', false, 'Ruled out because diabetes is not a recognised significant cause of CA-125 elevation; the well-established benign causes are gynaecological (endometriosis, fibroids, PID) and certain non-gynaecological conditions (heart failure, liver disease), not diabetes.', 1),
('da000000-0000-0000-0000-000000000042', 'B', 'Hyperthyroidism; CA-125 elevation is a recognised thyroid function marker in this condition', false, 'Ruled out because CA-125 is not associated with thyroid dysfunction; this option misattributes an unrelated endocrine condition as a cause of CA-125 elevation.', 2),
('da000000-0000-0000-0000-000000000042', 'C', 'Endometriosis; recognising this and other benign causes (e.g. fibroids, pelvic inflammatory disease, pregnancy, menstruation, other non-gynaecological conditions such as heart failure or liver disease) is important because CA-125 alone is not specific for malignancy and must be interpreted alongside imaging findings and validated risk scores such as the Risk of Malignancy Index (RMI)', true, 'Correct. CA-125 has significant limitations in specificity, being elevated in numerous benign gynaecological conditions (endometriosis being one of the most clinically important and commonly tested) as well as non-gynaecological conditions (heart failure, liver cirrhosis/ascites, pleural effusion) and physiological states (menstruation, pregnancy). Because of this, an elevated CA-125 alone should never be used in isolation to diagnose malignancy; it is combined with menopausal status and ultrasound findings in validated tools like the Risk of Malignancy Index (RMI) to better stratify risk and guide referral for specialist gynaecological oncology assessment.', 3),
('da000000-0000-0000-0000-000000000042', 'D', 'Iron deficiency anaemia; this commonly causes marked CA-125 elevation independent of any pelvic pathology', false, 'Ruled out because iron deficiency anaemia is not a recognised cause of CA-125 elevation; this is a distractor unrelated to the established benign causes of raised CA-125.', 4),
('da000000-0000-0000-0000-000000000042', 'E', 'CA-125 is entirely specific to malignant ovarian pathology and has no recognised benign causes of elevation', false, 'Ruled out because this is factually incorrect — CA-125 has numerous well-documented benign causes of elevation, which is precisely why it cannot be used alone to diagnose malignancy and must be combined with imaging and clinical risk scoring.', 5),
('da000000-0000-0000-0000-000000000043', 'A', 'Discontinue ADT, as the rising PSA despite castrate testosterone indicates the cancer is no longer androgen-dependent and hormonal suppression is futile', false, 'Ruled out because ADT should be continued in castration-resistant prostate cancer even though the disease is progressing despite castrate testosterone levels, as continued androgen suppression remains part of standard management and stopping it can allow testosterone to rise, potentially accelerating disease progression.', 1),
('da000000-0000-0000-0000-000000000043', 'B', 'Repeat testosterone testing is unnecessary; a single PSA rise alone is sufficient to diagnose treatment failure regardless of testosterone level', false, 'Ruled out because confirmation of castrate testosterone levels is an essential part of correctly diagnosing castration-resistant prostate cancer (distinguishing it from inadequate testosterone suppression, which would instead prompt review/intensification of ADT), so testosterone confirmation should not be skipped.', 2),
('da000000-0000-0000-0000-000000000043', 'C', 'This pattern indicates laboratory error, as PSA cannot rise while testosterone remains suppressed; repeat PSA testing alone is required with no other action', false, 'Ruled out because a rising PSA despite confirmed castrate testosterone is a well-recognised and expected pattern in castration-resistant prostate cancer, not a laboratory artefact, and requires appropriate oncological workup rather than being dismissed.', 3),
('da000000-0000-0000-0000-000000000043', 'D', 'Switch to a different GnRH agonist formulation, as this rising PSA suggests inadequate testosterone suppression from the current agent', false, 'Ruled out because testosterone has been confirmed to be at castrate levels on repeat testing, meaning the ADT is working as intended to suppress testosterone; switching formulations would not address the actual mechanism of progression, which is castration resistance.', 4),
('da000000-0000-0000-0000-000000000043', 'E', 'This represents biochemical progression to castration-resistant prostate cancer (CRPC); restaging imaging should be arranged and options for next-line therapy (e.g. androgen receptor pathway inhibitors, chemotherapy) should be considered while continuing ADT', true, 'Correct. A confirmed castrate testosterone level with a rising PSA on three consecutive measurements defines biochemical progression to castration-resistant prostate cancer. ADT (testosterone suppression) should be continued indefinitely even after progression to CRPC, since ongoing androgen suppression remains beneficial, while restaging imaging is arranged to assess for metastatic progression and next-line systemic therapy options (such as abiraterone, enzalutamide, docetaxel, or others depending on prior treatment and disease characteristics) are considered.', 5),
('da000000-0000-0000-0000-000000000044', 'A', 'FIT is specific for human haemoglobin and is not affected by dietary intake (e.g. red meat) or many medications, improving specificity and reducing false positives compared with gFOBT', true, 'Correct. FIT uses antibodies specific to human globin, meaning it is not confounded by dietary sources of blood/peroxidase activity (e.g. red meat, certain vegetables) or many medications that can cause false positives with guaiac-based testing, and it also allows for quantification of the amount of blood detected, enabling threshold-based referral decisions. This improves overall test performance (particularly specificity) and patient acceptability (no dietary restriction needed), which has supported the shift from gFOBT to FIT in national screening programmes.', 1),
('da000000-0000-0000-0000-000000000044', 'B', 'FIT can be performed as a blood test rather than requiring a stool sample, greatly improving patient compliance', false, 'Ruled out because FIT, like gFOBT, is a stool-based test detecting blood in faeces, not a blood test; this option misdescribes the nature of the test.', 2),
('da000000-0000-0000-0000-000000000044', 'C', 'FIT has 100% sensitivity for colorectal cancer, meaning a negative result completely excludes the diagnosis', false, 'Ruled out because no screening test, including FIT, has 100% sensitivity; a negative FIT reduces but does not eliminate the possibility of colorectal cancer, and symptomatic patients still require appropriate investigation regardless of a screening result.', 3),
('da000000-0000-0000-0000-000000000044', 'D', 'FIT requires no further investigation if positive, as it is diagnostic of colorectal cancer on its own', false, 'Ruled out because FIT is a screening test, not a diagnostic one; a positive result triggers referral for colonoscopy to achieve a definitive diagnosis, not a direct cancer diagnosis based on the FIT result alone.', 4),
('da000000-0000-0000-0000-000000000044', 'E', 'FIT detects both upper and lower gastrointestinal bleeding with equal sensitivity, broadening its diagnostic scope compared with gFOBT', false, 'Ruled out because FIT is generally more sensitive to lower GI (colorectal) bleeding, as globin is often degraded during transit from upper GI sources, meaning it is not equally sensitive across the whole GI tract; this is not the reason for its advantage over gFOBT in bowel screening.', 5),
('da000000-0000-0000-0000-000000000045', 'A', 'Annual mammography alone, as breast cancer is the predominant extra-colonic malignancy risk in Lynch syndrome', false, 'Ruled out because breast cancer is not one of the classically markedly elevated extra-colonic cancer risks specifically associated with Lynch syndrome (in contrast to BRCA1/2); endometrial cancer is the most clinically significant additional risk requiring specific surveillance in Lynch syndrome.', 1),
('da000000-0000-0000-0000-000000000045', 'B', 'Renal ultrasound surveillance, as renal cell carcinoma is the primary extra-colonic malignancy associated with Lynch syndrome', false, 'Ruled out because renal cell carcinoma is not a classic Lynch syndrome-associated malignancy; the Lynch syndrome tumour spectrum includes colorectal, endometrial, ovarian, gastric, urinary tract (less commonly), and other cancers, with endometrial cancer being the most important additional surveillance priority in women.', 2),
('da000000-0000-0000-0000-000000000045', 'C', 'Testicular ultrasound surveillance is a priority for this patient, given the association between Lynch syndrome and testicular cancer', false, 'Ruled out because this is not clinically relevant to a female patient and testicular cancer is not a recognised part of the Lynch syndrome tumour spectrum.', 3),
('da000000-0000-0000-0000-000000000045', 'D', 'Gynaecological surveillance for endometrial (and ovarian) cancer, given the substantially elevated lifetime risk of endometrial cancer associated with Lynch syndrome, with consideration of risk-reducing hysterectomy and bilateral salpingo-oophorectomy after completion of childbearing', true, 'Correct. Lynch syndrome (hereditary non-polyposis colorectal cancer), caused by pathogenic mismatch repair gene mutations including MLH1, confers a markedly elevated lifetime risk of colorectal cancer but also a substantially elevated risk of endometrial cancer (and to a lesser extent ovarian cancer), making gynaecological surveillance and consideration of risk-reducing gynaecological surgery after childbearing is complete an essential part of comprehensive management alongside more frequent (typically 1-2 yearly) colonoscopic surveillance from a younger age than average-risk individuals.', 4),
('da000000-0000-0000-0000-000000000045', 'E', 'No additional surveillance beyond colonoscopy is required, as Lynch syndrome confers risk only for colorectal cancer', false, 'Ruled out because Lynch syndrome is associated with a defined spectrum of extra-colonic cancers, most importantly endometrial cancer in women, and comprehensive management requires surveillance/risk-reduction strategies beyond colonoscopy alone.', 5),
('da000000-0000-0000-0000-000000000046', 'A', 'CA19-9 is only useful as a screening test in the general population and has no role in monitoring treatment response', false, 'Ruled out because CA19-9 is not recommended as a general population screening test (due to poor sensitivity/specificity for early detection) but is useful for monitoring treatment response and disease trend in patients with confirmed, CA19-9-producing pancreatic cancer, the opposite of what this option states.', 1),
('da000000-0000-0000-0000-000000000046', 'B', 'CA19-9 levels are unaffected by biliary obstruction and any elevation always indicates active malignancy', false, 'Ruled out because this is factually incorrect — benign biliary obstruction/cholestasis is a well-recognised confounder that can elevate CA19-9 independent of malignancy, making interpretation in the context of biliary dilatation more complex, not straightforward.', 2),
('da000000-0000-0000-0000-000000000046', 'C', 'Blood group O status invalidates CA19-9 testing entirely, requiring an alternative marker to be used in this patient', false, 'Ruled out because blood group O is not the confounding factor for CA19-9; the relevant genetic factor affecting CA19-9 production is Lewis antigen status (a different, though related, blood group antigen system), not ABO blood group specifically.', 3),
('da000000-0000-0000-0000-000000000046', 'D', 'CA19-9 can be falsely low or undetectable in individuals who are Lewis antigen-negative (approximately 5-10% of the population), regardless of tumour burden, and can also be elevated by benign biliary obstruction/cholestasis independent of malignancy', true, 'Correct. CA19-9 is a sialylated Lewis antigen, and individuals who are genetically Lewis antigen-negative (Le(a-b-) phenotype, roughly 5-10% of the population) cannot produce detectable CA19-9 regardless of tumour burden, meaning a normal or low CA19-9 does not exclude pancreatic cancer in this subgroup. Conversely, CA19-9 is also non-specifically elevated by benign biliary obstruction/cholestasis (as is present here, given the biliary dilatation), meaning an elevated level in this context reflects both cholestasis and potential tumour burden, and levels should ideally be reassessed after biliary decompression for more reliable interpretation and monitoring.', 4),
('da000000-0000-0000-0000-000000000046', 'E', 'CA19-9 is exclusively produced by pancreatic tissue, making it entirely specific for pancreatic malignancy', false, 'Ruled out because CA19-9 is not exclusively pancreatic in origin; it can be elevated in other gastrointestinal and hepatobiliary malignancies as well as benign hepatobiliary conditions, meaning it lacks the specificity this option claims.', 5),
('da000000-0000-0000-0000-000000000047', 'A', 'Reassure her that a single affected first-degree relative does not alter her risk category, and she should await standard population screening at the usual starting age', false, 'Ruled out because a first-degree relative diagnosed at a young age is a recognised risk factor that can shift a woman into a moderate or higher risk category depending on full formal risk calculation, meaning standard population screening timing alone may be insufficient without formal assessment.', 1),
('da000000-0000-0000-0000-000000000047', 'B', 'Arrange immediate bilateral risk-reducing mastectomy without further risk assessment or genetic testing', false, 'Ruled out because risk-reducing mastectomy is a significant intervention reserved for confirmed high-risk individuals (e.g. confirmed pathogenic mutation carriers or very high calculated lifetime risk) after formal assessment and counselling, not a default first step based on a single family history detail without further risk stratification.', 2),
('da000000-0000-0000-0000-000000000047', 'C', 'Refer to a family history/genetics clinic for formal risk assessment using a validated risk model, as her family history may place her in a moderate or high-risk category warranting earlier and/or more frequent mammographic surveillance than the general population screening programme, with consideration of genetic testing', true, 'Correct. A single first-degree relative diagnosed with breast cancer at a relatively young age (under 50) is sufficient to warrant formal risk assessment through a family history/genetics clinic, using validated models (e.g. Tyrer-Cuzick, BOADICEA) to calculate lifetime risk and stratify into population, moderate, or high-risk screening pathways, which may include earlier initiation of mammographic surveillance (sometimes with MRI in higher-risk categories) and consideration of germline genetic testing, rather than simply waiting for standard population screening age.', 3),
('da000000-0000-0000-0000-000000000047', 'D', 'Start annual mammography immediately at age 35 for the general population without any formal risk calculation, as this is the standard approach for anyone with an affected relative', false, 'Ruled out because screening intensity and starting age should be individualised based on formal risk calculation via a family history/genetics service, not applied uniformly to everyone with any affected relative regardless of the specifics of that family history.', 4),
('da000000-0000-0000-0000-000000000047', 'E', 'Recommend she undergo CA-125 and pelvic ultrasound surveillance instead, as breast cancer family history primarily necessitates ovarian cancer screening', false, 'Ruled out because CA-125/pelvic ultrasound relates to ovarian cancer risk assessment (more relevant to BRCA-associated risk specifically), not the appropriate primary response to a breast cancer family history query, which should focus on breast cancer risk stratification and appropriate breast screening pathway.', 5),
('da000000-0000-0000-0000-000000000048', 'A', 'This single small rise may represent normal biological variation rather than true progression; per standard response criteria (e.g. PCWG), a confirmatory rising PSA on a subsequent measurement (and correlation with imaging/clinical status) is needed before concluding treatment failure and changing therapy', true, 'Correct. Standard prostate cancer response criteria (such as the Prostate Cancer Working Group, PCWG, criteria) require a confirmed rise in PSA (typically on two consecutive occasions above a defined threshold from nadir) before declaring biochemical progression, precisely because isolated small fluctuations can occur without representing true treatment failure. In an asymptomatic patient with stable recent imaging, the appropriate approach is close monitoring with a repeat PSA rather than an immediate change in effective systemic therapy based on a single small rise.', 1),
('da000000-0000-0000-0000-000000000048', 'B', 'This confirms definitive treatment failure, and abiraterone should be stopped immediately in favour of an alternative systemic therapy', false, 'Ruled out because a single small PSA rise does not meet standard criteria for confirmed biochemical progression; changing an effective, well-tolerated therapy based on one isolated data point risks prematurely abandoning a treatment that may still be providing benefit.', 2),
('da000000-0000-0000-0000-000000000048', 'C', 'PSA is no longer a useful marker once a patient starts abiraterone, so no further monitoring is required', false, 'Ruled out because PSA remains a useful (though not sole) monitoring tool during abiraterone therapy; this option incorrectly dismisses its ongoing relevance rather than describing the correct interpretive framework for isolated rises.', 3),
('da000000-0000-0000-0000-000000000048', 'D', 'Any rise in PSA, however small, always indicates true disease progression regardless of the clinical or imaging context', false, 'Ruled out because this contradicts standard response criteria, which specifically require confirmatory, sustained rises correlated with clinical/imaging findings rather than treating any single fluctuation as definitive progression.', 4),
('da000000-0000-0000-0000-000000000048', 'E', 'Repeat imaging should be arranged immediately regardless of PSA trend confirmation, and treatment changed based on the imaging result alone without further PSA monitoring', false, 'Ruled out because while imaging remains an important part of overall assessment, the standard, resource-appropriate approach to an isolated small PSA rise in an asymptomatic, stable patient is confirmatory PSA testing first, rather than immediately escalating to repeat imaging and treatment change based on a single ambiguous marker result.', 5),
('da000000-0000-0000-0000-000000000049', 'A', 'Reassure the patient and continue routine six-monthly ultrasound and AFP surveillance without further imaging, as ultrasound is the gold-standard surveillance tool', false, $x$Ruled out because a significantly rising AFP trend should not be dismissed based on a normal ultrasound alone, given ultrasound's known limitations in a cirrhotic liver; further, more sensitive imaging is warranted to avoid missing an early, potentially curable HCC.$x$, 1),
('da000000-0000-0000-0000-000000000049', 'B', 'Arrange contrast-enhanced multiphase CT or MRI of the liver, as a significantly rising AFP in a cirrhotic patient under surveillance warrants further cross-sectional imaging even when ultrasound is unremarkable', true, 'Correct. Ultrasound has limited sensitivity for detecting small hepatocellular carcinomas, particularly in a nodular cirrhotic liver, and a significantly rising AFP trend in a patient under HCC surveillance is a recognised indication for further, more sensitive cross-sectional imaging (multiphase contrast-enhanced CT or MRI, which can demonstrate the characteristic arterial-phase hyperenhancement with portal-venous washout of HCC) even when ultrasound does not show a definite lesion, since early detection significantly improves the chance of curative treatment.', 2),
('da000000-0000-0000-0000-000000000049', 'C', 'Proceed directly to liver biopsy of a representative area of the cirrhotic liver, as this is more sensitive than any form of imaging for detecting early HCC', false, 'Ruled out because blind biopsy of a cirrhotic liver without a target lesion has poor sensitivity for detecting focal HCC and carries procedural risk; targeted cross-sectional imaging to identify a lesion (which can then be characterised or biopsied if needed) is the appropriate next step.', 3),
('da000000-0000-0000-0000-000000000049', 'D', 'Repeat AFP again in six months as part of routine surveillance, since a single rising trend does not warrant a change in the surveillance interval', false, 'Ruled out because this AFP rise is already confirmed on two consecutive measurements and is of a magnitude that should prompt earlier, more sensitive imaging now rather than simply continuing the standard six-monthly interval unchanged.', 4),
('da000000-0000-0000-0000-000000000049', 'E', 'Diagnose hepatocellular carcinoma definitively based on the AFP trend alone and refer for liver transplant assessment without further imaging', false, 'Ruled out because AFP elevation alone, without a corresponding lesion demonstrated on imaging (or histological confirmation), is not sufficient to definitively diagnose HCC; imaging characterisation is required first to identify and stage any lesion before treatment pathway decisions are made.', 5),
('da000000-0000-0000-0000-000000000050', 'A', 'Both markers should have normalised completely within two weeks of surgery if the tumour was fully resected; failure to normalise by this point always indicates surgical failure requiring re-exploration', false, $x$Ruled out because complete normalisation within two weeks is not expected given the biological half-lives involved (particularly AFP's longer half-life of 5-7 days meaning full clearance of even appropriately-declining markers takes several weeks); assessment is based on the rate of decline relative to expected half-life, not an assumption of complete normalisation by an arbitrary early timepoint, and re-exploration is not the appropriate response to marker kinetics.$x$, 1),
('da000000-0000-0000-0000-000000000050', 'B', 'Marker levels are unreliable in the post-operative period and should not be measured again until three months after surgery', false, 'Ruled out because serial marker measurement in the weeks following orchidectomy is a core, clinically important part of post-operative surveillance for assessing adequacy of tumour clearance, not something to be deferred for three months.', 2),
('da000000-0000-0000-0000-000000000050', 'C', 'A decline in AFP but not beta-hCG (or vice versa) is never clinically significant, as only the overall trend across both markers matters', false, 'Ruled out because each marker should be assessed against its own specific expected half-life; discordant behaviour between the two markers (e.g. one declining appropriately while the other plateaus) can be clinically informative regarding residual disease and should not be dismissed.', 3),
('da000000-0000-0000-0000-000000000050', 'D', 'These marker levels indicate inevitable disease progression regardless of further decline, and adjuvant chemotherapy should be started immediately without further marker or imaging assessment', false, 'Ruled out because a decision to proceed to adjuvant chemotherapy should be based on continued serial marker trend assessment (against expected half-lives) and staging imaging, not made immediately from a single two-week post-operative value without allowing for the expected time course of marker decline.', 4),
('da000000-0000-0000-0000-000000000050', 'E', 'The markers should be tracked serially against their expected biological half-lives (AFP approximately 5-7 days, beta-hCG approximately 24-36 hours); failure to decline appropriately according to these half-lives suggests residual or metastatic disease requiring further staging and treatment', true, 'Correct. After complete resection of a germ cell tumour, tumour markers are expected to fall according to their known biological half-lives (AFP roughly 5-7 days, beta-hCG roughly 24-36 hours); serial marker measurement over the following weeks is used to assess whether decline is proceeding as expected. A slower-than-expected decline (or a plateau/rise) suggests residual disease (retroperitoneal or distant metastasis) not addressed by orchidectomy alone, prompting further staging imaging and consideration of systemic chemotherapy, whereas an appropriately declining trend supports adequate surgical clearance and appropriate ongoing surveillance.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('da000000-0000-0000-0000-000000000001', 'Trastuzumab cardiotoxicity (Type II) is typically reversible and not dose-dependent, in contrast to anthracycline cardiotoxicity (Type I), which is dose-dependent and often irreversible.', 1),
('da000000-0000-0000-0000-000000000001', 'An asymptomatic LVEF fall of ≥10 points to below 50% warrants withholding trastuzumab and starting heart failure therapy, with re-evaluation before considering rechallenge.', 2),
('da000000-0000-0000-0000-000000000001', 'Baseline and serial LVEF monitoring is mandatory during trastuzumab therapy, particularly when given after anthracyclines, which sensitise the myocardium to further HER2-pathway-related injury.', 3),
('da000000-0000-0000-0000-000000000002', 'Febrile neutropenia (fever ≥38°C with neutrophils <0.5 x10^9/L) requires empirical broad-spectrum IV antibiotics within 1 hour of presentation, regardless of apparent clinical wellness.', 1),
('da000000-0000-0000-0000-000000000002', 'Blood cultures should be taken but must never delay empirical antibiotic administration in suspected neutropenic sepsis.', 2),
('da000000-0000-0000-0000-000000000002', 'Formal risk stratification (e.g. MASCC score) is needed before considering oral/outpatient management; it should not be assumed based on clinical impression alone.', 3),
('da000000-0000-0000-0000-000000000003', 'Oxaliplatin causes a distinctive acute, cold-triggered peripheral and pharyngolaryngeal dysaesthesia within hours of infusion, separate from its cumulative dose-dependent chronic sensory neuropathy.', 1),
('da000000-0000-0000-0000-000000000003', 'Acute oxaliplatin neurotoxicity is managed with cold avoidance and does not usually require dose modification, whereas persistent/cumulative neuropathy does.', 2),
('da000000-0000-0000-0000-000000000003', $x$5-fluorouracil's key toxicities to distinguish include coronary vasospasm (cardiotoxicity), hand-foot syndrome, and diarrhoea/mucositis, not cold-induced neuropathy.$x$, 3),
('da000000-0000-0000-0000-000000000004', 'Bleomycin pulmonary toxicity is dose-dependent and potentially fatal; DLCO decline is a sensitive early marker that precedes symptoms or radiographic change and should prompt drug discontinuation.', 1),
('da000000-0000-0000-0000-000000000004', 'When bleomycin is stopped for pulmonary toxicity within a combination regimen (e.g. BEP), the remaining agents are typically continued as they retain efficacy.', 2),
('da000000-0000-0000-0000-000000000004', 'Patients who have received bleomycin should have supplemental oxygen used cautiously (including during future anaesthesia), as hyperoxia can precipitate or worsen bleomycin-associated lung injury even after treatment has stopped.', 3),
('da000000-0000-0000-0000-000000000005', 'Anthracyclines are potent vesicants; extravasation is a clinical diagnosis based on pain, erythema, swelling and blistering, and does not require confirmation by loss of blood return.', 1),
('da000000-0000-0000-0000-000000000005', 'Management of anthracycline extravasation involves stopping the infusion, aspirating residual drug, cooling the area, and giving IV dexrazoxane within 6 hours to limit tissue necrosis.', 2),
('da000000-0000-0000-0000-000000000005', 'Hyaluronidase and warm compresses are used for vinca alkaloid extravasation, illustrating that extravasation management is agent-specific and must not be generalised across vesicant classes.', 3),
('da000000-0000-0000-0000-000000000006', 'DPD deficiency is an important, under-recognised cause of severe or fatal fluoropyrimidine (5-FU/capecitabine) toxicity, since DPD is the rate-limiting catabolic enzyme for these drugs.', 1),
('da000000-0000-0000-0000-000000000006', 'Recurrent severe toxicity across separate fluoropyrimidine exposures should raise suspicion of DPD deficiency and prompt genotyping/phenotyping before any further fluoropyrimidine exposure, with permanent discontinuation if deficiency is confirmed.', 2),
('da000000-0000-0000-0000-000000000006', 'UGT1A1 polymorphisms are relevant to irinotecan toxicity and TPMT deficiency to thiopurine toxicity — recognising which pharmacogenomic pathway maps to which drug class is a key discriminator in exam scenarios.', 3),
('da000000-0000-0000-0000-000000000007', 'Delayed methotrexate clearance with rising creatinine signals methotrexate-induced nephrotoxicity, which can create a self-perpetuating cycle of prolonged toxic exposure and worsening renal function.', 1),
('da000000-0000-0000-0000-000000000007', 'Management of delayed clearance escalates folinic acid dosing (guided by measured levels), ensures hydration and urinary alkalinisation, and reserves glucarpidase for severe, refractory elevation with renal impairment.', 2),
('da000000-0000-0000-0000-000000000007', $x$Glucarpidase rapidly inactivates circulating methotrexate enzymatically and is distinct from folinic acid, which rescues normal cells from methotrexate's antifolate effect but does not reduce the methotrexate level itself.$x$, 3),
('da000000-0000-0000-0000-000000000008', 'Immune checkpoint inhibitor colitis is graded by stool frequency/severity and guides management: grade 1 (mild) may allow continued therapy with monitoring, grade 2 requires withholding therapy and corticosteroids, and grade 3-4 requires hospitalisation, IV steroids, and consideration of infliximab or vedolizumab if steroid-refractory.', 1),
('da000000-0000-0000-0000-000000000008', 'Combination ipilimumab/nivolumab carries a substantially higher risk of immune-related adverse events, including colitis, than either agent alone.', 2),
('da000000-0000-0000-0000-000000000008', 'Infective causes (including C. difficile) must be excluded before attributing diarrhoea to immune-related colitis, but a negative infective workup in this clinical context supports prompt immunosuppression rather than further diagnostic delay.', 3),
('da000000-0000-0000-0000-000000000009', 'After a febrile neutropenia episode, secondary G-CSF prophylaxis in subsequent cycles is preferred over empirical dose reduction when maintaining dose intensity is important for treatment efficacy.', 1),
('da000000-0000-0000-0000-000000000009', 'G-CSF is typically started 24-72 hours after chemotherapy completion and continued until adequate neutrophil recovery, avoiding administration too close to chemotherapy dosing.', 2),
('da000000-0000-0000-0000-000000000009', 'Primary G-CSF prophylaxis is recommended from cycle 1 for regimens with a high (>20%) baseline febrile neutropenia risk; secondary prophylaxis addresses regimens where risk becomes apparent only after an event occurs.', 3),
('da000000-0000-0000-0000-000000000010', 'Cisplatin ototoxicity is cumulative, dose-dependent and largely irreversible, typically beginning with high-frequency sensorineural hearing loss that can progress to affect speech frequencies with continued dosing.', 1),
('da000000-0000-0000-0000-000000000010', 'Baseline and serial audiometry should be performed during cisplatin therapy to detect ototoxicity early and inform decisions about dose modification or substitution (e.g. carboplatin), balanced against oncological efficacy needs.', 2),
('da000000-0000-0000-0000-000000000010', $x$Cisplatin's other major dose-limiting toxicities — nephrotoxicity and peripheral neuropathy — are also cumulative and should be actively monitored in parallel with ototoxicity.$x$, 3),
('da000000-0000-0000-0000-000000000011', 'Neutropenic enterocolitis (typhlitis) classically presents with right iliac fossa/periumbilical pain, fever and profound neutropenia after cytotoxic chemotherapy, with CT showing caecal/ascending colon wall thickening.', 1),
('da000000-0000-0000-0000-000000000011', 'First-line management is conservative (bowel rest, broad-spectrum antibiotics, correction of cytopenias), with surgery reserved for perforation, uncontrolled sepsis, or major haemorrhage due to high surgical mortality in this neutropenic population.', 2),
('da000000-0000-0000-0000-000000000011', 'Distinguishing typhlitis from C. difficile colitis and appendicitis by the clinical context (profound neutropenia post-chemotherapy) and CT distribution is a key exam discriminator.', 3),
('da000000-0000-0000-0000-000000000012', 'Vinca alkaloids (vincristine, vinblastine) cause dose-dependent peripheral sensorimotor and autonomic neuropathy via microtubule/axonal transport disruption, classically causing constipation, jaw pain, areflexia, and progressive motor weakness.', 1),
('da000000-0000-0000-0000-000000000012', 'Development of motor signs (e.g. foot drop) during vinca alkaloid therapy is a significant red flag requiring dose reduction or discontinuation to prevent permanent deficit.', 2),
('da000000-0000-0000-0000-000000000012', 'Each ABVD component has a distinct dose-limiting toxicity: doxorubicin (cardiotoxicity), bleomycin (pulmonary fibrosis), vinblastine (neurotoxicity/myelosuppression), dacarbazine (nausea/myelosuppression) — matching drug to toxicity pattern is a core exam skill.', 3),
('da000000-0000-0000-0000-000000000013', 'Taxane hypersensitivity reactions typically occur within minutes of starting infusion, even with standard steroid/antihistamine premedication, and can present with hypotension, bronchospasm and flushing mimicking anaphylaxis.', 1),
('da000000-0000-0000-0000-000000000013', 'Management follows standard anaphylaxis protocol (stop infusion, IM adrenaline, oxygen, fluids, antihistamines/steroids), distinct from managing extravasation, which is a local rather than systemic reaction.', 2),
('da000000-0000-0000-0000-000000000013', 'Future chemotherapy after a severe hypersensitivity reaction may still be possible via slower infusion rates, enhanced premedication, or formal desensitisation protocols rather than automatic permanent discontinuation.', 3),
('da000000-0000-0000-0000-000000000014', 'Malignant spinal cord compression is a time-critical oncological emergency: high-dose dexamethasone should be started immediately on clinical suspicion, without waiting for definitive imaging or specialist review to be arranged.', 1),
('da000000-0000-0000-0000-000000000014', 'Definitive treatment (surgery vs radiotherapy) depends on factors including number of compression levels, expected prognosis, spinal stability, and rate of neurological decline, and requires urgent same-day MDT input.', 2),
('da000000-0000-0000-0000-000000000014', 'Neurological outcome correlates strongly with pre-treatment functional status and time to treatment — patients who are still ambulant or have only recently lost function have the best chance of recovery with prompt intervention.', 3),
('da000000-0000-0000-0000-000000000015', 'Endovascular stenting provides the fastest symptomatic relief in malignant SVC obstruction and is preferred over waiting for chemotherapy/radiotherapy response when symptoms are significant, especially with mechanical compression plus thrombus.', 1),
('da000000-0000-0000-0000-000000000015', $x$Tissue diagnosis should be obtained before definitive oncological treatment (chemotherapy/radiotherapy) where the patient's condition allows, since treatment choice depends heavily on histology (e.g. SCLC vs lymphoma vs NSCLC).$x$, 2),
('da000000-0000-0000-0000-000000000015', 'Anticoagulation is considered when SVC thrombus is present, in addition to mechanical decompression, once bleeding risk has been assessed.', 3),
('da000000-0000-0000-0000-000000000016', 'Severe/symptomatic malignancy-associated hypercalcaemia is managed with aggressive IV 0.9% saline rehydration first, followed by IV bisphosphonate (e.g. zoledronic acid) once rehydrated, as bisphosphonates take 2-4 days for full effect.', 1),
('da000000-0000-0000-0000-000000000016', 'Loop diuretics are not routine first-line therapy and should not be given before adequate rehydration, as they can worsen volume depletion.', 2),
('da000000-0000-0000-0000-000000000016', 'PTHrP-mediated humoral hypercalcaemia of malignancy is common with squamous cell carcinomas (lung, head and neck, cervix, oesophagus) and should be distinguished from bone-metastasis-mediated (osteolytic) hypercalcaemia, though management principles overlap.', 3),
('da000000-0000-0000-0000-000000000017', 'Differentiation syndrome typically occurs within the first 1-2 weeks of starting ATRA (or arsenic trioxide) for APL, presenting with fever, dyspnoea, pulmonary infiltrates, pleural/pericardial effusions, oedema and a rapidly rising white cell count.', 1),
('da000000-0000-0000-0000-000000000017', 'High-dose dexamethasone is first-line treatment, started promptly on clinical suspicion without waiting for confirmatory tests, given the risk of rapid respiratory and haemodynamic deterioration.', 2),
('da000000-0000-0000-0000-000000000017', 'ATRA is generally continued alongside corticosteroids in mild-moderate differentiation syndrome (as it is also curative therapy) and only temporarily withheld in severe, life-threatening presentations.', 3),
('da000000-0000-0000-0000-000000000018', 'Symptomatic hyperleukocytosis (leukostasis) with neurological, visual or respiratory symptoms is a medical emergency requiring urgent cytoreduction, most classically seen in AML with very high blast counts.', 1),
('da000000-0000-0000-0000-000000000018', 'Red cell transfusion should be avoided or given very cautiously in hyperleukocytosis before cytoreduction, as it increases blood viscosity and can worsen leukostasis.', 2),
('da000000-0000-0000-0000-000000000018', 'Tumour lysis syndrome prophylaxis should be started alongside cytoreductive therapy in hyperleukocytosis given the very high cell turnover risk once treatment begins.', 3),
('da000000-0000-0000-0000-000000000019', 'A reliably documented fever (even if since resolved) with rigors in a patient who is neutropenic or at high risk of neutropenia should be treated as febrile neutropenia — normalisation of temperature on arrival does not exclude significant sepsis.', 1),
('da000000-0000-0000-0000-000000000019', 'Management decisions in suspected neutropenic sepsis should not be delayed pending repeat blood counts; empirical antibiotics follow prompt clinical assessment and cultures.', 2),
('da000000-0000-0000-0000-000000000019', 'Rigors are a particularly concerning symptom suggesting bacteraemia and should heighten, not lower, clinical suspicion for serious infection in this context.', 3),
('da000000-0000-0000-0000-000000000020', 'Immune checkpoint inhibitors can cause endocrinopathies including hypophysitis and primary adrenal insufficiency, which can present acutely as adrenal crisis with hypotension, hyponatraemia, hyperkalaemia and hypoglycaemia.', 1),
('da000000-0000-0000-0000-000000000020', 'Suspected adrenal crisis requires immediate IV hydrocortisone and fluid resuscitation without waiting for confirmatory dynamic endocrine testing, given the risk of rapid deterioration and death if untreated.', 2),
('da000000-0000-0000-0000-000000000020', 'Unlike many immune-related adverse events affecting other organs, immune-related endocrinopathies (adrenal insufficiency, hypothyroidism, hypophysitis) are usually permanent, requiring long-term hormone replacement even after immunotherapy is adjusted.', 3),
('da000000-0000-0000-0000-000000000021', 'Overt liver failure from extensive hepatic replacement by metastatic malignancy carries a very poor short-term prognosis, and further systemic anti-cancer therapy is usually contraindicated due to impaired drug clearance and toxicity risk.', 1),
('da000000-0000-0000-0000-000000000021', 'Liver transplantation is contraindicated in the presence of active metastatic malignancy, distinguishing this from liver failure due to other reversible or non-malignant causes.', 2),
('da000000-0000-0000-0000-000000000021', 'Recognising when the appropriate shift is to symptom-focused palliative care and honest prognostic discussion, rather than further invasive investigation or disease-directed treatment, is a core Part 2 management skill.', 3),
('da000000-0000-0000-0000-000000000022', 'DOACs are now first-line for most cancer-associated thrombosis per current guidance, given comparable/superior efficacy to LMWH and oral convenience, except in patients with high GI/urothelial bleeding risk or significant drug interactions, where LMWH remains preferred.', 1),
('da000000-0000-0000-0000-000000000022', 'Warfarin is inferior to LMWH/DOACs for cancer-associated thrombosis due to reduced efficacy and practical difficulties maintaining therapeutic anticoagulation during active cancer treatment.', 2),
('da000000-0000-0000-0000-000000000022', 'IVC filters and unfractionated heparin have specific, narrow indications in cancer-associated thrombosis rather than being first-line options.', 3),
('da000000-0000-0000-0000-000000000023', 'Factors favouring surgical decompression (plus stabilisation) over radiotherapy alone in malignant cord compression include spinal instability, relative tumour radioresistance, single-level disease, good performance status, and longer prognosis.', 1),
('da000000-0000-0000-0000-000000000023', 'Post-operative radiotherapy is typically given after surgical decompression to consolidate local tumour control.', 2),
('da000000-0000-0000-0000-000000000023', 'Estimated prognosis and performance status are central to treatment-intensity decisions in cord compression, mirroring their importance across oncological emergency management generally.', 3),
('da000000-0000-0000-0000-000000000024', 'Checkpoint inhibitor pneumonitis presents with dyspnoea, cough and hypoxia, often with bilateral ground-glass or organising pneumonia patterns on CT, and requires infection to be excluded before attributing symptoms to immunotherapy.', 1),
('da000000-0000-0000-0000-000000000024', 'Grade-based management: mild (grade 1) pneumonitis may allow continued monitoring, while grade ≥2 (symptomatic/hypoxic) requires withholding the checkpoint inhibitor and starting corticosteroids, with escalation to additional immunosuppression if steroid-refractory.', 2),
('da000000-0000-0000-0000-000000000024', 'Distinguishing checkpoint inhibitor pneumonitis from infection, disease progression, radiation pneumonitis and pulmonary embolism by history, timeline and imaging pattern is essential, as management differs substantially between these.', 3),
('da000000-0000-0000-0000-000000000025', 'TLS risk stratification considers tumour type, bulk/proliferation rate, and baseline biochemistry (not renal function alone); high-grade lymphomas with high tumour burden are inherently high-risk.', 1),
('da000000-0000-0000-0000-000000000025', 'Rasburicase is preferred over allopurinol for high-risk TLS prophylaxis because it actively reduces existing urate, whereas allopurinol only prevents further urate formation.', 2),
('da000000-0000-0000-0000-000000000025', 'Aggressive IV hydration alongside urate-lowering therapy, started before chemotherapy and continued through the peak lysis window, is central to TLS prevention in high-risk patients.', 3),
('da000000-0000-0000-0000-000000000026', $x$Cardiac tamponade is a clinical and echocardiographic diagnosis (pulsus paradoxus, raised JVP with Kussmaul's sign, muffled heart sounds, hypotension, diastolic chamber collapse) requiring urgent pericardial drainage regardless of the underlying malignant cause.$x$, 1),
('da000000-0000-0000-0000-000000000026', 'Diuretics and excessive preload reduction should be avoided in tamponade, as adequate filling pressures help maintain cardiac output against the compressive effusion until drainage is achieved.', 2),
('da000000-0000-0000-0000-000000000026', 'Malignant pericardial effusions have a high recurrence rate after simple aspiration, so an indwelling catheter, sclerosing agent, or pericardial window is often used alongside initial drainage to reduce recurrence.', 3),
('da000000-0000-0000-0000-000000000027', 'Lambert-Eaton myasthenic syndrome is caused by antibodies against presynaptic voltage-gated calcium channels, causing proximal weakness that improves with sustained exertion, autonomic dysfunction, and an incremental response to high-frequency repetitive nerve stimulation — contrasting with myasthenia gravis.', 1),
('da000000-0000-0000-0000-000000000027', 'LEMS is strongly paraneoplastic, most commonly associated with small cell lung cancer, and identification of LEMS should prompt a thorough search for underlying malignancy.', 2),
('da000000-0000-0000-0000-000000000027', 'Distinguishing LEMS from myasthenia gravis by the direction of change in weakness with exertion and the electrophysiological pattern (incremental vs decremental) is a key exam discriminator.', 3),
('da000000-0000-0000-0000-000000000028', 'Anti-Yo (PCA-1) antibodies are strongly associated with paraneoplastic cerebellar degeneration linked to ovarian and breast carcinoma, and should prompt targeted pelvic/breast imaging.', 1),
('da000000-0000-0000-0000-000000000028', 'Paraneoplastic neurological syndromes frequently precede the diagnosis of the underlying malignancy, so a thorough, antibody-directed cancer search is essential even with no prior cancer history.', 2),
('da000000-0000-0000-0000-000000000028', 'Matching specific onconeural antibodies to their associated tumours (anti-Yo–ovarian/breast, anti-Hu–SCLC, anti-Ma2–testicular, anti-CV2/CRMP5–SCLC/thymoma) is a key discriminator tested in paraneoplastic syndrome questions.', 3),
('da000000-0000-0000-0000-000000000029', 'PTHrP-mediated humoral hypercalcaemia of malignancy is most classically associated with squamous cell carcinomas and presents with elevated PTHrP and appropriately suppressed endogenous PTH.', 1),
('da000000-0000-0000-0000-000000000029', 'Calcitriol-mediated hypercalcaemia (via ectopic 1-alpha-hydroxylase) is classically associated with lymphoma, distinguishing it mechanistically and by tumour type from PTHrP-mediated hypercalcaemia.', 2),
('da000000-0000-0000-0000-000000000029', 'True ectopic PTH secretion by non-parathyroid tumours is exceptionally rare, so an elevated PTH in a cancer patient with hypercalcaemia should prompt consideration of coincidental primary hyperparathyroidism rather than assuming an ectopic source.', 3),
('da000000-0000-0000-0000-000000000030', 'Paraneoplastic SIADH is common in small cell lung cancer due to ectopic ADH secretion, presenting as euvolaemic hyponatraemia with inappropriately concentrated urine and elevated urine sodium, after excluding renal, thyroid and adrenal causes.', 1),
('da000000-0000-0000-0000-000000000030', 'Fluid restriction is first-line for asymptomatic/mildly symptomatic SIADH-related hyponatraemia; hypertonic saline is reserved for severe/symptomatic cases, with careful rate-of-correction monitoring to avoid osmotic demyelination syndrome regardless of method.', 2),
('da000000-0000-0000-0000-000000000030', '0.9% saline can worsen hyponatraemia in true SIADH, an important distinction from hypovolaemic hyponatraemia, where isotonic saline is appropriate first-line treatment.', 3),
('da000000-0000-0000-0000-000000000031', 'Dermatomyositis has a stronger and more clinically significant malignancy association than polymyositis, with risk highest around the time of diagnosis and for the subsequent 1-3 years.', 1),
('da000000-0000-0000-0000-000000000031', 'Malignancy screening in new dermatomyositis should be comprehensive and age/sex-appropriate (commonly including CT chest/abdomen/pelvis and gynaecological assessment in women), not limited to a single cancer type.', 2),
('da000000-0000-0000-0000-000000000031', 'Treatment of the myositis (immunosuppression) and the search for an underlying malignancy should proceed in parallel rather than sequentially.', 3),
('da000000-0000-0000-0000-000000000032', 'Both primary hyperparathyroidism and PTHrP-mediated humoral hypercalcaemia of malignancy cause hypercalcaemia with hypophosphataemia, but a suppressed PTH level is the key initial discriminator pointing towards a malignancy-related cause.', 1),
('da000000-0000-0000-0000-000000000032', 'Calcitriol (1,25-dihydroxyvitamin D) tends to be elevated in primary hyperparathyroidism (via PTH-stimulated renal 1-alpha-hydroxylase) but low/low-normal in PTHrP-mediated hypercalcaemia, since PTHrP is a weaker stimulator of this enzyme.', 2),
('da000000-0000-0000-0000-000000000032', 'Squamous cell lung cancer is a classic tumour type associated with PTHrP-mediated humoral hypercalcaemia, and this mechanism should be actively considered even when incidental biochemical findings (e.g. unexplained raised ALP) are present.', 3),
('da000000-0000-0000-0000-000000000033', 'Anti-NMDA receptor encephalitis is strongly associated with ovarian teratoma in women of reproductive age, and pelvic imaging should be arranged urgently as part of the diagnostic workup.', 1),
('da000000-0000-0000-0000-000000000033', 'First-line immunotherapy (corticosteroids, IVIG, plasma exchange) should be started promptly on diagnosis without waiting for tumour identification, given the risk of severe, life-threatening neurological deterioration.', 2),
('da000000-0000-0000-0000-000000000033', 'When an associated teratoma is found, its surgical removal is an important adjunct to immunotherapy and improves neurological outcomes, illustrating the interplay between oncological and neurological/immunological management in paraneoplastic syndromes.', 3),
('da000000-0000-0000-0000-000000000034', 'Anti-Hu (ANNA-1) antibodies are associated with small cell lung cancer and a range of paraneoplastic neurological syndromes including cerebellar degeneration, sensory neuronopathy and limbic encephalitis.', 1),
('da000000-0000-0000-0000-000000000034', 'A new paraneoplastic antibody-positive syndrome in a patient with a history of an associated cancer (even in prior remission) should prompt urgent restaging, as it may herald disease recurrence before it is otherwise detectable.', 2),
('da000000-0000-0000-0000-000000000034', 'Paraneoplastic neurological syndromes often respond poorly to immunotherapy alone if the underlying tumour is not identified and treated, reinforcing the priority of the oncological search.', 3),
('da000000-0000-0000-0000-000000000035', 'Stauffer syndrome is a paraneoplastic cholestatic hepatic dysfunction associated with renal cell carcinoma, occurring in the absence of hepatic metastases and mediated by tumour cytokine (e.g. IL-6) production.', 1),
('da000000-0000-0000-0000-000000000035', 'Recognising Stauffer syndrome avoids unnecessary invasive hepatic investigation and correctly directs management towards treatment of the underlying renal cell carcinoma, after which the hepatic dysfunction typically resolves.', 2),
('da000000-0000-0000-0000-000000000035', 'Systemic paraneoplastic features (fever, weight loss, raised inflammatory markers) alongside organ-specific dysfunction without direct tumour infiltration are a recurring theme across paraneoplastic syndromes and should prompt consideration of a unifying paraneoplastic explanation.', 3),
('da000000-0000-0000-0000-000000000036', 'Cancer-associated retinopathy (associated with antibodies such as anti-recoverin) causes progressive visual loss and reduced electroretinography response, often with a deceptively normal-appearing fundus, and is classically linked to small cell lung cancer but also breast and gynaecological cancers.', 1),
('da000000-0000-0000-0000-000000000036', 'A new paraneoplastic syndrome in a patient with a past cancer history, even years after apparent remission, should prompt urgent restaging to look for recurrence, as the neurological/ophthalmological syndrome may be the first clinical clue.', 2),
('da000000-0000-0000-0000-000000000036', 'Early recognition and treatment (addressing the underlying cancer and considering immunosuppression) offers the best chance of preventing irreversible visual loss in cancer-associated retinopathy.', 3),
('da000000-0000-0000-0000-000000000037', $x$Ectopic ACTH syndrome (classically from small cell lung cancer or bronchial carcinoid) causes rapidly progressive Cushing's syndrome with severe hypokalaemic metabolic alkalosis and often less prominent classic centripetal features than pituitary-driven disease, due to the speed of onset.$x$, 1),
('da000000-0000-0000-0000-000000000037', $x$Failure of cortisol to suppress with high-dose dexamethasone supports an ectopic (non-pituitary) ACTH source, in contrast to the partial suppression typically seen in pituitary Cushing's disease.$x$, 2),
('da000000-0000-0000-0000-000000000037', 'Severe hypokalaemia in ectopic ACTH syndrome is immediately life-threatening and requires urgent correction alongside rapid cortisol-lowering medical therapy (e.g. metyrapone, ketoconazole), as source control via cancer treatment/surgery is often not immediately achievable.', 3),
('da000000-0000-0000-0000-000000000038', 'Hypertrophic pulmonary osteoarthropathy causes clubbing, symmetrical joint pain/swelling, and periosteal new bone formation on the distal long bones, and is most strongly associated with non-small cell lung cancer (particularly adenocarcinoma).', 1),
('da000000-0000-0000-0000-000000000038', 'HPOA should prompt urgent investigation and staging of the underlying malignancy, as symptoms often improve or resolve with successful treatment of the primary tumour.', 2),
('da000000-0000-0000-0000-000000000038', 'Distinguishing paraneoplastic (secondary) HPOA from primary/inherited hypertrophic osteoarthropathy and from inflammatory arthritis relies on age, clinical context, and the presence of an underlying mass lesion.', 3),
('da000000-0000-0000-0000-000000000039', 'Risk-reducing bilateral salpingo-oophorectomy is the most effective ovarian cancer mortality-reduction strategy for BRCA1/2 carriers, as CA-125/ultrasound screening has not reliably reduced mortality due to aggressive, often late-detected tumour biology.', 1),
('da000000-0000-0000-0000-000000000039', 'Timing of RRSO is typically earlier for BRCA1 (around age 35-40) than BRCA2 carriers (around 40-45), reflecting differing penetrance and typical age of ovarian cancer onset between the two genes.', 2),
('da000000-0000-0000-0000-000000000039', 'RRSO also confers some reduction in breast cancer risk via reduced oestrogen exposure, illustrating the interconnected risk-reduction benefits of this procedure in BRCA carriers.', 3),
('da000000-0000-0000-0000-000000000040', 'A progressive, rising trend in CEA (rather than a single elevated or fluctuating value) after curative colorectal cancer treatment is a significant marker of possible recurrence and should prompt further investigation even when recent imaging was normal.', 1),
('da000000-0000-0000-0000-000000000040', 'PET-CT has higher sensitivity than standard CT for detecting small-volume or occult recurrent colorectal cancer and is considered when repeat conventional imaging is unremarkable despite a concerning CEA trend.', 2),
('da000000-0000-0000-0000-000000000040', 'CEA elevation alone is not diagnostic of recurrence and must be correlated with imaging (and potentially biopsy) findings before committing to a change in treatment strategy.', 3),
('da000000-0000-0000-0000-000000000041', 'AFP is never produced by pure seminoma; any AFP elevation in a testicular germ cell tumour indicates a non-seminomatous component and changes management/classification to NSGCT regardless of the dominant histological pattern seen on biopsy.', 1),
('da000000-0000-0000-0000-000000000041', 'Beta-hCG can be mildly elevated in a minority of pure seminomas (from syncytiotrophoblastic giant cells), so isolated beta-hCG elevation does not exclude seminoma the way AFP elevation does.', 2),
('da000000-0000-0000-0000-000000000041', 'LDH is a less specific marker reflecting tumour burden/turnover across germ cell tumour subtypes and is used mainly for staging/prognostic (IGCCCG) risk classification rather than histological subtyping.', 3),
('da000000-0000-0000-0000-000000000042', 'CA-125 lacks specificity for malignancy, being elevated in endometriosis, fibroids, pelvic inflammatory disease, pregnancy, menstruation, and non-gynaecological conditions such as heart failure and liver disease/ascites.', 1),
('da000000-0000-0000-0000-000000000042', 'The Risk of Malignancy Index (RMI) combines CA-125 level, menopausal status, and ultrasound features to better risk-stratify an adnexal mass and guide appropriate referral, rather than relying on CA-125 alone.', 2),
('da000000-0000-0000-0000-000000000042', 'An elevated CA-125 with a complex adnexal mass on imaging still requires this combined risk assessment and specialist gynaecological oncology referral rather than either dismissing the marker or over-interpreting it in isolation.', 3),
('da000000-0000-0000-0000-000000000043', 'Castration-resistant prostate cancer is defined by disease progression (biochemical, radiological or clinical) despite confirmed castrate testosterone levels (<50 ng/dL), and testosterone confirmation is an essential diagnostic step.', 1),
('da000000-0000-0000-0000-000000000043', 'ADT/testosterone suppression is continued indefinitely even after progression to CRPC, as ongoing androgen suppression retains benefit alongside next-line systemic therapies.', 2),
('da000000-0000-0000-0000-000000000043', 'Next-line options in CRPC (androgen receptor pathway inhibitors, chemotherapy, and others) are selected based on disease burden, symptoms, and prior treatment exposure, guided by restaging imaging.', 3),
('da000000-0000-0000-0000-000000000044', $x$FIT's specificity for human globin avoids the dietary and drug-related false positives seen with guaiac-based FOBT, and allows quantification of faecal blood to guide referral thresholds.$x$, 1),
('da000000-0000-0000-0000-000000000044', 'FIT is a screening test that identifies patients at higher risk requiring colonoscopy; it is not diagnostic of colorectal cancer on its own, and a negative result does not fully exclude the diagnosis, particularly in symptomatic patients.', 2),
('da000000-0000-0000-0000-000000000044', 'FIT is generally more sensitive to lower GI than upper GI bleeding, since globin degrades during upper GI transit, relevant to understanding its role specifically in colorectal cancer screening.', 3),
('da000000-0000-0000-0000-000000000045', 'Lynch syndrome confers a markedly elevated lifetime risk of both colorectal and endometrial cancer, with endometrial cancer being the most important additional surveillance priority in affected women.', 1),
('da000000-0000-0000-0000-000000000045', 'Risk-reducing hysterectomy and bilateral salpingo-oophorectomy should be discussed with Lynch syndrome carriers after completion of childbearing, given the elevated endometrial and ovarian cancer risk.', 2),
('da000000-0000-0000-0000-000000000045', 'The Lynch syndrome tumour spectrum (colorectal, endometrial, ovarian, gastric, urinary tract, and others) differs meaningfully from other hereditary cancer syndromes (e.g. BRCA-associated breast/ovarian cancer), and matching syndrome to correct surveillance priorities is a key exam skill.', 3),
('da000000-0000-0000-0000-000000000046', 'Lewis antigen-negative individuals (roughly 5-10% of the population) cannot produce detectable CA19-9 regardless of tumour burden, so a normal CA19-9 does not reliably exclude pancreatic cancer in this subgroup.', 1),
('da000000-0000-0000-0000-000000000046', 'Benign biliary obstruction/cholestasis can elevate CA19-9 independent of malignancy, so levels are ideally reassessed after biliary decompression for more reliable interpretation, especially when used for monitoring rather than diagnosis.', 2),
('da000000-0000-0000-0000-000000000046', 'CA19-9 is not recommended as a general population screening test for pancreatic cancer due to insufficient sensitivity/specificity for early-stage disease, but has a more established role in monitoring treatment response in confirmed CA19-9-producing tumours.', 3),
('da000000-0000-0000-0000-000000000047', 'A first-degree relative diagnosed with breast cancer at a young age warrants formal risk assessment via a family history/genetics service using validated risk models, rather than either reassurance or an assumption of high risk without calculation.', 1),
('da000000-0000-0000-0000-000000000047', 'Screening pathways are stratified (population, moderate, high risk) based on calculated lifetime risk, with higher-risk categories potentially including earlier mammography and MRI surveillance.', 2),
('da000000-0000-0000-0000-000000000047', 'Risk-reducing surgery is reserved for confirmed high-risk individuals after full risk assessment and counselling, not offered as a default response to a single family history detail.', 3),
('da000000-0000-0000-0000-000000000048', 'Standard prostate cancer response criteria (e.g. PCWG) require a confirmed, sustained rise in PSA (often on two consecutive measurements) before declaring biochemical progression, avoiding premature treatment changes based on isolated fluctuations.', 1),
('da000000-0000-0000-0000-000000000048', 'Treatment decisions in metastatic prostate cancer should integrate PSA trend, symptoms, and imaging findings together rather than relying on any single data point in isolation.', 2),
('da000000-0000-0000-0000-000000000048', 'Prematurely discontinuing an effective systemic therapy based on an unconfirmed, isolated small biochemical change risks losing disease control without a confirmed indication that the current treatment has failed.', 3),
('da000000-0000-0000-0000-000000000049', 'Ultrasound has limited sensitivity for detecting small HCC in a cirrhotic liver, so a significantly rising AFP trend under surveillance should prompt further cross-sectional imaging (multiphase CT/MRI) even when ultrasound is unremarkable.', 1),
('da000000-0000-0000-0000-000000000049', 'Multiphase contrast-enhanced imaging can demonstrate the characteristic arterial-phase hyperenhancement with portal-venous washout pattern that allows non-invasive radiological diagnosis of HCC in cirrhotic patients, without requiring biopsy in typical cases.', 2),
('da000000-0000-0000-0000-000000000049', 'AFP trend (not just a single value) is the key surveillance signal; a confirmed rising trend carries greater significance than an isolated mild elevation, which can occur with hepatic inflammation/regeneration in cirrhosis.', 3),
('da000000-0000-0000-0000-000000000050', 'AFP has a biological half-life of approximately 5-7 days and beta-hCG approximately 24-36 hours; post-orchidectomy marker decline is assessed against these expected half-lives, not an assumption of immediate normalisation.', 1),
('da000000-0000-0000-0000-000000000050', 'Failure of markers to decline as expected (plateau or slower decline than predicted by half-life) suggests residual or metastatic germ cell tumour disease, prompting further staging and consideration of chemotherapy.', 2),
('da000000-0000-0000-0000-000000000050', 'Serial marker measurement in the post-operative period is a key part of germ cell tumour management, guiding decisions about surveillance versus further active treatment.', 3);
